function act(obs, mem) {
    if (!mem.init) {
        mem.init = true;
        mem.stuckCount = 0;
        mem.unstuckTicks = 0;
        mem.stuckAttempts = 0;
        mem.prevX = obs.x;
        mem.prevY = obs.y;
        mem.prevHeading = obs.heading;
        mem.headingBias = 0;
    }

    // --- Heading bias estimation from GPS velocity vs compass ---
    let dX = obs.x - mem.prevX;
    let dY = obs.y - mem.prevY;
    let gpsDist = Math.sqrt(dX * dX + dY * dY);
    let dHeading = obs.heading - mem.prevHeading;
    while (dHeading > 180) dHeading -= 360;
    while (dHeading < -180) dHeading += 360;

    if (gpsDist > 0.04 && Math.abs(dHeading) < 3) {
        let gpsHeading = Math.atan2(dY, dX) * 180 / Math.PI;
        let bias = gpsHeading - obs.heading;
        while (bias > 180) bias -= 360;
        while (bias < -180) bias += 360;
        if (Math.abs(bias) < 45) {
            mem.headingBias = mem.headingBias * 0.97 + bias * 0.03;
        }
    }
    mem.prevX = obs.x;
    mem.prevY = obs.y;
    mem.prevHeading = obs.heading;

    // --- Navigation to target ---
    let dx = obs.targetX - obs.x;
    let dy = obs.targetY - obs.y;
    let distToTarget = Math.sqrt(dx * dx + dy * dy);
    let desiredHeading = Math.atan2(dy, dx) * 180 / Math.PI;

    let corrHeading = obs.heading + mem.headingBias;
    let headingError = desiredHeading - corrHeading;
    while (headingError > 180) headingError -= 360;
    while (headingError < -180) headingError += 360;

    // --- Obstacle avoidance (potential field) ---
    let rays = obs.rays;
    let angles = [-60, -30, 0, 30, 60];
    let obstacleSteer = 0;
    let minRay = 10;

    for (let i = 0; i < 5; i++) {
        let d = rays[i];
        if (d < minRay) minRay = d;
        if (d < 4) {
            let urgency = Math.pow((4 - d) / 4, 1.5) * 3;
            obstacleSteer -= urgency * Math.sin(angles[i] * Math.PI / 180);
        }
    }

    if (rays[2] < 2.5) {
        let leftOpen = rays[3] + rays[4];
        let rightOpen = rays[0] + rays[1];
        obstacleSteer += (leftOpen > rightOpen ? 0.6 : -0.6);
    }

    // --- Speed control ---
    let speed = 0.7;
    if (distToTarget < 3) speed = Math.min(speed, 0.15 + 0.18 * distToTarget);
    if (minRay < 0.5) speed = 0;
    else if (minRay < 2.5) speed = Math.min(speed, 0.1 + 0.25 * minRay);

    let absErr = Math.abs(headingError);
    if (absErr > 120) speed = 0;
    else if (absErr > 60) speed = Math.min(speed, 0.1);
    else if (absErr > 30) speed = Math.min(speed, 0.35);

    // --- Steering ---
    let turn;
    if (absErr > 120) {
        turn = Math.sign(headingError);
    } else if (absErr > 60) {
        turn = Math.sign(headingError) * 0.6 + obstacleSteer;
    } else {
        turn = headingError * 0.015 + obstacleSteer;
    }
    turn = Math.max(-1, Math.min(1, turn));

    let left = speed - turn;
    let right = speed + turn;
    left = Math.max(-1, Math.min(1, left));
    right = Math.max(-1, Math.min(1, right));

    // --- Stuck detection and recovery ---
    if (gpsDist < 0.01 && Math.abs(obs.speed) < 0.05) {
        mem.stuckCount++;
    } else {
        mem.stuckCount = Math.max(0, mem.stuckCount - 2);
    }

    if (mem.stuckCount > 15) {
        mem.stuckCount = 0;
        mem.unstuckTicks = 40;
        mem.stuckAttempts++;
    }

    if (mem.unstuckTicks > 0) {
        mem.unstuckTicks--;
        if (mem.unstuckTicks > 35) {
            left = -0.4;
            right = -0.3;
        } else if (mem.unstuckTicks > 15) {
            let openSide = (rays[3] + rays[4] > rays[0] + rays[1]) ? 1 : -1;
            let turnDir = (mem.stuckAttempts % 2 === 1) ? openSide : -openSide;
            left = 0.5 * turnDir;
            right = -0.5 * turnDir;
        } else {
            left = 0.3;
            right = 0.5;
        }
    }

    return { left, right };
}

function act(obs, mem) {
    if (!mem.init) {
        mem.init = true;
        mem.stuckCount = 0;
        mem.spinCount = 0;
        mem.recoverMode = 0;
        mem.recoverStep = 0;
        mem.lastX = obs.x;
        mem.lastY = obs.y;
        mem.lastHeading = obs.heading;
    }

    let dx = obs.x - mem.lastX;
    let dy = obs.y - mem.lastY;
    let moved = Math.sqrt(dx * dx + dy * dy);
    mem.lastX = obs.x;
    mem.lastY = obs.y;

    let dh = obs.heading - mem.lastHeading;
    while (dh > 180) dh -= 360;
    while (dh < -180) dh += 360;
    mem.lastHeading = obs.heading;

    if (moved < 0.003) mem.stuckCount++;
    else mem.stuckCount = Math.max(0, mem.stuckCount - 2);

    if (moved < 0.01 && Math.abs(dh) > 1) mem.spinCount++;
    else mem.spinCount = Math.max(0, mem.spinCount - 2);

    let rays = obs.rays;
    for (let i = 0; i < 5; i++) {
        if (!isFinite(rays[i]) || rays[i] < 0) rays[i] = 0.1;
        if (rays[i] > 10) rays[i] = 10;
    }

    if ((mem.stuckCount > 15 || mem.spinCount > 25) && mem.recoverMode === 0) {
        mem.recoverMode = 1;
        mem.recoverStep = 0;
        mem.stuckCount = 0;
        mem.spinCount = 0;
        mem.recoverAttempts = (mem.recoverAttempts || 0) + 1;
        let openL = rays[3] + rays[4];
        let openR = rays[0] + rays[1];
        mem.turnDir = openL > openR ? 1 : -1;
        if (mem.recoverAttempts % 2 === 0) mem.turnDir = -mem.turnDir;
    }

    if (mem.recoverMode > 0) {
        mem.recoverStep++;
        let left, right;
        if (mem.recoverStep < 25) {
            left = -0.5; right = -0.5;
        } else if (mem.recoverStep < 60) {
            left = -0.3 * mem.turnDir; right = 0.3 * mem.turnDir;
        } else if (mem.recoverStep < 80) {
            left = 0.5; right = 0.5;
        } else {
            mem.recoverMode = 0;
        }
        return { left, right };
    }

    let dxT = obs.targetX - obs.x;
    let dyT = obs.targetY - obs.y;
    let distToTarget = Math.sqrt(dxT * dxT + dyT * dyT);
    let desiredHeading = Math.atan2(dyT, dxT) * 180 / Math.PI;

    let headingError = desiredHeading - obs.heading;
    while (headingError > 180) headingError -= 360;
    while (headingError < -180) headingError += 360;
    let absErr = Math.abs(headingError);

    let pushLeft = 0, pushRight = 0;
    let minRay = 10;

    for (let i = 0; i < 5; i++) {
        let d = rays[i];
        if (d < minRay) minRay = d;
        if (d < 3.0) {
            let closeness = (3.0 - d) / 3.0;
            if (i === 0 || i === 1) pushLeft += closeness;
            if (i === 3 || i === 4) pushRight += closeness;
            if (i === 2) {
                if (rays[3] + rays[4] >= rays[0] + rays[1]) pushLeft += closeness * 2;
                else pushRight += closeness * 2;
            }
        }
    }

    let avoid = (pushLeft - pushRight) * 0.2;
    avoid = Math.max(-0.3, Math.min(0.3, avoid));

    let headingTurn = headingError * 0.008;
    if (Math.abs(avoid) > 0.1) headingTurn *= 0.3;

    let turn = headingTurn + avoid;
    turn = Math.max(-0.4, Math.min(0.4, turn));

    let speed;
    if (absErr > 150) speed = 0.2;
    else if (absErr > 90) speed = 0.3;
    else if (absErr > 45) speed = 0.4;
    else if (absErr > 20) speed = 0.5;
    else speed = 0.6;

    if (minRay < 2.5) speed = Math.min(speed, 0.1 + 0.15 * minRay);
    if (minRay < 0.5) speed = Math.min(speed, 0.03);
    if (distToTarget < 3) speed = Math.min(speed, 0.05 + 0.1 * distToTarget);
    if (distToTarget < 1.2) speed = Math.min(speed, 0.05);
    speed = Math.max(0.05, speed);

    let left = speed - turn;
    let right = speed + turn;

    return {
        left: Math.max(-1, Math.min(1, left)),
        right: Math.max(-1, Math.min(1, right))
    };
}

