        mem.prevY = obs.y;
        mem.prevH = obs.heading;
        mem.compassBias = 0;
        mem.lastTX = obs.targetX;
        mem.lastTY = obs.targetY;
    }

    // Reset on target change
    if (obs.targetX !== mem.lastTX || obs.targetY !== mem.lastTY) {
        mem.bestDist = 1e9;
        mem.stuckT = 0;
        mem.smoothErr = 0;
    }
    mem.lastTX = obs.targetX;
    mem.lastTY = obs.targetY;

    // Compass bias from GPS velocity (when moving straight)
    let gx = obs.x - mem.prevX;
    let gy = obs.y - mem.prevY;
    let gDist = Math.sqrt(gx * gx + gy * gy);
    let dH = obs.heading - mem.prevH;
    while (dH > 180) dH -= 360;
    while (dH < -180) dH += 360;
    if (gDist > 0.08 && Math.abs(dH) < 3 && obs.speed > 0.1) {
        let gH = Math.atan2(gy, gx) * 180 / Math.PI;
        let b = gH - obs.heading;
        while (b > 180) b -= 360;
        while (b < -180) b += 360;
        if (Math.abs(b) < 60) mem.compassBias = mem.compassBias * 0.98 + b * 0.02;
    }
    mem.prevX = obs.x;
    mem.prevY = obs.y;
    mem.prevH = obs.heading;

    let corrH = obs.heading + mem.compassBias;
    while (corrH > 180) corrH -= 360;
    while (corrH < -180) corrH += 360;

    // Target distance
    let dx = obs.targetX - obs.x;
    let dy = obs.targetY - obs.y;
    let dist = Math.sqrt(dx * dx + dy * dy);

    // Stuck: no target-distance improvement over many ticks
    if (dist < mem.bestDist - 0.3) {
        mem.bestDist = dist;
        mem.stuckT = 0;
    } else {
        mem.stuckT++;
    }

    // Recovery mode
    if (mem.recT > 0) {
        mem.recT--;
        let l, r;
        if (mem.recT > 25) { l = -0.3; r = -0.3; }
        else if (mem.recT > 8) { l = -0.2 * mem.recDir; r = 0.2 * mem.recDir; }
        else { l = 0.35; r = 0.35; }
        mem.prevL = mem.prevL * 0.3 + l * 0.7;
        mem.prevR = mem.prevR * 0.3 + r * 0.7;
        return { left: mem.prevL, right: mem.prevR };
    }

    if (mem.stuckT > 150) {
        mem.recT = 35;
        mem.stuckT = 0;
        mem.bestDist = 1e9;
        mem.recCnt++;
        let ol = obs.rays[3] + obs.rays[4];
        let orv = obs.rays[0] + obs.rays[1];
        mem.recDir = ol > orv ? 1 : -1;
        if (mem.recCnt % 2 === 0) mem.recDir = -mem.recDir;
    }

    // Heading error (smoothed to fight oscillation from lag)
    let desired = dist > 0.01 ? Math.atan2(dy, dx) * 180 / Math.PI : corrH;
    let hErr = desired - corrH;
    while (hErr > 180) hErr -= 360;
    while (hErr < -180) hErr += 360;
    mem.smoothErr = mem.smoothErr * 0.85 + hErr * 0.15;

    // Sanitise rays
    let rays = obs.rays;
    let minR = 10;
    for (let i = 0; i < 5; i++) {
        let r = rays[i];
        if (!isFinite(r) || r < 0) r = 0.1;
        if (r > 10) r = 10;
        rays[i] = r;
        if (r < minR) minR = r;
    }

    // Emergency: very close obstacle -> turn away
    if (minR < 0.8) {
        let ci = 0;
        for (let i = 1; i < 5; i++) if (rays[i] < rays[ci]) ci = i;
        let ta = ci <= 2 ? 0.4 : -0.4;
        mem.prevL = mem.prevL * 0.2 + (0.05 - ta) * 0.8;
        mem.prevR = mem.prevR * 0.2 + (0.05 + ta) * 0.8;
        return { left: mem.prevL, right: mem.prevR };
    }

    // Obstacle avoidance
    let avoid = 0;
    if (rays[0] < 2.5) avoid += (2.5 - rays[0]) * 0.1;
    if (rays[1] < 2.0) avoid += (2.0 - rays[1]) * 0.06;
    if (rays[3] < 2.0) avoid -= (2.0 - rays[3]) * 0.06;
    if (rays[4] < 2.5) avoid -= (2.5 - rays[4]) * 0.1;
    if (rays[2] < 3.5) {
        let lO = Math.min(10, rays[3]) + Math.min(10, rays[4]);
        let rO = Math.min(10, rays[0]) + Math.min(10, rays[1]);
        let urg = (3.5 - rays[2]) / 3.5;
        avoid += urg * 0.35 * (lO > rO ? 1 : -1);
    }
    avoid = Math.max(-0.3, Math.min(0.3, avoid));

    // Steering (gentle to work with physics lag)
    let turn = mem.smoothErr * 0.008 + avoid;
    turn = Math.max(-0.3, Math.min(0.3, turn));

    // Speed
    let sErr = Math.abs(mem.smoothErr);
    let speed;
    if (sErr > 100) speed = 0.1;
    else if (sErr > 60) speed = 0.2;
    else if (sErr > 30) speed = 0.35;
    else speed = 0.5;
    if (minR < 3) speed = Math.min(speed, 0.08 + 0.1 * minR);
    if (dist < 2) speed = Math.min(speed, 0.05 + 0.15 * dist);
    speed = Math.max(0.05, speed);

    let dl = Math.max(-1, Math.min(1, speed - turn));
    let dr = Math.max(-1, Math.min(1, speed + turn));

    // Smooth commands to avoid oscillation with lagged physics
    mem.prevL = mem.prevL * 0.3 + dl * 0.7;
    mem.prevR = mem.prevR * 0.3 + dr * 0.7;

    return { left: mem.prevL, right: mem.prevR };
}

function act(obs, mem) {
    if (!mem.init) {
        mem.init = true;
        mem.px = obs.x;
        mem.py = obs.y;
        mem.ph = obs.heading;
        mem.bh = 0;
        mem.smErr = 0;
        mem.cl = 0;
        mem.cr = 0;
        mem.tc = 0;
        mem.st = 0;
        mem.bd = 1e9;
        mem.rp = 0;
        mem.rs = 0;
        mem.rd = 1;
        mem.rc = 0;
        mem.ltx = obs.targetX;
        mem.lty = obs.targetY;
        mem.ad = 0;
    }

