        mem.bd = 1e9;
        mem.st = 0;
    }
    mem.ltx = obs.targetX;
    mem.lty = obs.targetY;

    var gx = obs.x - mem.px;
    var gy = obs.y - mem.py;
    var gDist = Math.sqrt(gx * gx + gy * gy);
    var dh = obs.heading - mem.ph;
    while (dh > 180) dh -= 360;
    while (dh < -180) dh += 360;

    if (gDist > 0.005 && gDist < 0.1 && Math.abs(dh) < 2 && obs.speed > 0.05) {
        var gh = Math.atan2(gy, gx) * 180 / Math.PI;
        if (obs.speed < -0.05) gh = ((gh + 180 + 360) % 360) - 180;
        var diff = gh - obs.heading;
        while (diff > 180) diff -= 360;
        while (diff < -180) diff += 360;
        if (Math.abs(diff) < 90) {
            mem.bh = mem.bh * 0.99 + diff * 0.01;
        }
    }
    mem.px = obs.x;
    mem.py = obs.y;
    mem.ph = obs.heading;

    var eh = obs.heading + mem.bh;
    while (eh > 180) eh -= 360;
    while (eh < -180) eh += 360;

    var r = [];
    for (var i = 0; i < 5; i++) {
        var v = obs.rays[i];
        r.push((isFinite(v) && v > 0.05) ? Math.min(v, 10) : 0.05);
    }
    var minR = Math.min(r[0], r[1], r[2], r[3], r[4]);

    var tx = obs.targetX - obs.x;
    var ty = obs.targetY - obs.y;
    var dist = Math.sqrt(tx * tx + ty * ty);

    if (dist < mem.bd - 0.1) {
        mem.bd = dist;
        mem.st = 0;
    } else {
        mem.st++;
    }

    if (mem.rp > 0) {
        mem.rs++;
        var l, rr;
        if (mem.rp === 1) {
            l = -0.12;
            rr = -0.12;
            if (mem.rs >= 25) { mem.rp = 2; mem.rs = 0; }
        } else if (mem.rp === 2) {
            l = -0.06 * mem.rd;
            rr = 0.06 * mem.rd;
            if (mem.rs >= 70) { mem.rp = 3; mem.rs = 0; }
        } else {
            l = 0.15;
            rr = 0.15;
            if (mem.rs >= 30) { mem.rp = 0; mem.rs = 0; }
        }
        mem.cl = mem.cl * 0.7 + l * 0.3;
        mem.cr = mem.cr * 0.7 + rr * 0.3;
        return { left: mem.cl, right: mem.cr };
    }

    if (mem.st > 150) {
        mem.rp = 1;
        mem.rs = 0;
        mem.st = 0;
        mem.bd = 1e9;
        mem.rc++;
        var oL = r[3] + r[4], oR = r[0] + r[1];
        mem.rd = (oL > oR) ? 1 : -1;
        if (mem.rc % 2 === 0) mem.rd = -mem.rd;
    }

    var desired = Math.atan2(ty, tx) * 180 / Math.PI;
    var hErr = desired - eh;
    while (hErr > 180) hErr -= 360;
    while (hErr < -180) hErr += 360;

    mem.smErr = mem.smErr * 0.85 + hErr * 0.15;
    if (Math.abs(mem.smErr) < 3) mem.smErr *= 0.9;

    var targetTurn = mem.smErr * 0.002;

    if (minR < 3.5) {
        var oL2 = r[3] + r[4], oR2 = r[0] + r[1];
        var urg = (3.5 - minR) / 3.5;

        if (r[2] < 3) {
            var sd = (oL2 > oR2) ? 1 : -1;
            if (mem.ad !== 0) sd = mem.ad;
            else mem.ad = sd;
            targetTurn += sd * urg * 0.03;
        }
        if (r[3] < 1.5) targetTurn -= urg * 0.02;
        if (r[4] < 1.5) targetTurn -= urg * 0.02;
        if (r[0] < 1.5) targetTurn += urg * 0.02;
        if (r[1] < 1.5) targetTurn += urg * 0.02;
        if (r[2] > 4) mem.ad = 0;
    } else {
        mem.ad = 0;
    }

    var maxDelta = (minR < 3) ? 0.01 : 0.005;
    var tDelta = targetTurn - mem.tc;
    tDelta = Math.max(-maxDelta, Math.min(maxDelta, tDelta));
    mem.tc += tDelta;
    mem.tc = Math.max(-0.08, Math.min(0.08, mem.tc));

    if (minR < 0.8) {
        var ci = 0;
        for (var j = 1; j < 5; j++) if (r[j] < r[ci]) ci = j;
        var eT = (ci <= 1) ? 0.05 : (ci >= 3) ? -0.05 : ((r[3] + r[4] > r[0] + r[1]) ? 0.05 : -0.05);
        mem.tc = eT;
        mem.cl = mem.cl * 0.3 + (0.02 - eT) * 0.7;
        mem.cr = mem.cr * 0.3 + (0.02 + eT) * 0.7;
        return { left: mem.cl, right: mem.cr };
    }

    var ae = Math.abs(mem.smErr);
    var speed;
    if (ae > 35) speed = 0.15;
    else if (ae > 15) speed = 0.3;
    else speed = 0.4;

    if (r[2] < 3.5) speed = Math.min(speed, 0.03 + 0.08 * r[2]);
    if (minR < 1.5) speed = Math.min(speed, 0.2);
    if (minR < 0.8) speed = Math.min(speed, 0.1);
    if (dist < 3) speed = Math.min(speed, 0.1 + 0.05 * dist);
    if (dist < 1.5) speed = Math.min(speed, 0.05);

    var dl = speed - mem.tc;
    var dr = speed + mem.tc;
    dl = Math.max(-1, Math.min(1, dl));
    dr = Math.max(-1, Math.min(1, dr));

    mem.cl = mem.cl * 0.5 + dl * 0.5;
    mem.cr = mem.cr * 0.5 + dr * 0.5;

    return {
        left: Math.max(-1, Math.min(1, mem.cl)),
        right: Math.max(-1, Math.min(1, mem.cr))
    };
}

