      base *= 0.82;
    }

    if (speed > 1.65) {
      base *= 0.62;
    }

    base = Math.min(
      base,
      boundaryCap
    );

    if (Math.abs(steer) > 0.52) {
      base = Math.min(base, 0.22);
    }

    if (Math.abs(steer) > 0.72) {
      base = Math.min(base, 0.10);
    }

    let hardNow = false;

    if (hardBoundary || hardFront || hardSide) {
