  if (targetAngle > 135) {
    base = 0.02;
  } else if (targetAngle > 105) {
    base = 0.08;
  } else if (targetAngle > 75) {
    base = 0.20;
  } else if (targetAngle > 45) {
    base = 0.38;
  } else {
    base = 0.62;
  }

