    base *= clamp(
      0.44 + targetDistance * 0.11,
      0.44,
      1
    );
  }

  if (targetDistance < 1.60) {
    base = Math.min(base, 0.24);
  }

  if (targetDistance < 1.10) {
    base = Math.min(base, 0.13);
  }

  if (speed > 1.25) {
    base *= 0.80;
  }

  if (speed > 1.65) {
    base *= 0.62;
  }

  let steer =
    0.20 *
    clamp(
      targetBearing / 80,
      -1,
      1
    );

  if (targetAngle > 105) {
    steer =
      0.22 *
      (targetBearing >= 0 ? 1 : -1);
  }

  steer -= clamp(
    mem._headingRate * 0.0020,
    -0.24,
    0.24
  );

  if (!corridorLike) {
    steer +=
      0.16 *
      (
        danger(rays[1], 1.55) -
        danger(rays[3], 1.55)
      );

    steer +=
      0.07 *
      (
        danger(rays[0], 1.20) -
        danger(rays[4], 1.20)
      );
