    steer +=
      0.16 *
      clamp(
        (leftNear - rightNear) / 1.20,
        -1,
        1
      );

    base = Math.min(base, 0.45);
  }

  if (sideThreat) {
    base = Math.min(base, 0.36);
  }

  if (frontBlocked) {
