  steer += boundarySteer;

  if (frontEnvelope < 2.40) {
    base = Math.min(base, 0.48);
  }

  if (frontEnvelope < 1.85) {
    base = Math.min(base, 0.30);
  }

  if (frontEnvelope < 1.20) {
    base = Math.min(base, 0.12);
  }

  if (sideClose) {
    base *= 0.76;
  }

  base = Math.min(
    base,
    boundaryCap
  );

  if (Math.abs(steer) > 0.52) {
    base = Math.min(base, 0.24);
  }

  if (Math.abs(steer) > 0.72) {
    base = Math.min(base, 0.12);
  }

  let hardNow = false;

  if (hardBoundary || hardFront || hardSide) {
    let emergencySide = chooseTurnSide();

    if (hardBoundary) {
      emergencySide =
        boundaryRel >= 0 ? 1 : -1;
    }

    base = speed > 0.35 ? -0.10 : 0;

    steer =
      emergencySide * 0.82 -
      clamp(
        mem._headingRate * 0.0007,
        -0.12,
        0.12
      );

    hardNow = true;
  }

  const urgent =
    frontBlocked ||
    sideThreat ||
    sideClose ||
    boundaryThreat ||
    hardBoundary ||
    hardFront ||
    hardSide;

