  const oldHasTarget =
    finite(mem._v5LastTargetX) &&
    finite(mem._v5LastTargetY);

  const targetChanged =
    targetIndex !== mem._v5TargetIndex ||
    hasTarget !== oldHasTarget ||
    (
      hasTarget &&
      oldHasTarget &&
      Math.hypot(
        targetX - mem._v5LastTargetX,
        targetY - mem._v5LastTargetY
      ) > 0.75
    );

  const targetDistance = hasTarget
    ? Math.hypot(
        targetX - x,
        targetY - y
      )
    : 1e9;

  if (targetChanged) {
    mem._v5TargetIndex = targetIndex;
    mem._v5LastTargetX = hasTarget ? targetX : NaN;
    mem._v5LastTargetY = hasTarget ? targetY : NaN;

    mem._v5Mode = 0;
    mem._v5Stall = 0;
    mem._v5AvoidStart = now;
    mem._v5HitDist = targetDistance;
    mem._v5BestDist = targetDistance;
    mem._v5LastProgress = now;
    mem._v5ClearSince = 0;
  }

  mem._v5PrevX = x;
  mem._v5PrevY = y;
  mem._v5LastHeading = heading;
  mem._v5LastT = now;

  const rawRays = new Array(5);

  for (let i = 0; i < 5; i++) {
    let q = obs.rays && finite(obs.rays[i])
      ? obs.rays[i]
      : 10;

    rawRays[i] = clamp(q, 0, 10);
  }

  if (finite(obs.distanceAhead)) {
    rawRays[2] = Math.min(
      rawRays[2],
      clamp(obs.distanceAhead, 0, 10)
    );
  }

  if (
    !Array.isArray(mem._v5RayFilter) ||
    mem._v5RayFilter.length !== 5
  ) {
    mem._v5RayFilter = rawRays.slice();
  } else {
    for (let i = 0; i < 5; i++) {
      const alpha = rawRays[i] < mem._v5RayFilter[i]
        ? 0.80
        : 0.24;

      mem._v5RayFilter[i] +=
        alpha * (
          rawRays[i] - mem._v5RayFilter[i]
        );
    }
  }

  const rays = new Array(5);

  for (let i = 0; i < 5; i++) {
    rays[i] = Math.min(
      rawRays[i],
      mem._v5RayFilter[i]
    );
  }

  const navHeading = wrap(
    heading + mem._v5HeadingOffset
  );

  const globalTargetBearing = hasTarget
    ? Math.atan2(
        targetY - y,
        targetX - x
      ) / DEG
    : 0;

  const targetBearing = wrap(
    globalTargetBearing - navHeading
  );

  const rightNear = Math.min(
    rays[0],
    rays[1]
  );

  const leftNear = Math.min(
    rays[3],
    rays[4]
  );

  const centerRange = rays[2];

  const corridorLike =
    centerRange > 1.65 &&
    rightNear < 1.65 &&
    leftNear < 1.65 &&
    Math.abs(rightNear - leftNear) < 0.80;

  const narrowCorridor =
    corridorLike &&
    Math.min(rightNear, leftNear) < 1.08;

  const corridorSafe =
    corridorLike &&
    centerRange > 2.0 &&
    rays[1] > 0.72 &&
    rays[3] > 0.72;

  const dynamicFront =
    1.55 + Math.min(
      0.90,
      speed * 0.55
    );

  const frontRisk = Math.min(
    centerRange,
    rays[1] + 0.55,
    rays[3] + 0.55,
    rays[0] + 0.85,
    rays[4] + 0.85
  );

  let frontBlocked =
    centerRange < dynamicFront;

  if (
    !corridorSafe &&
    frontRisk <
      1.30 + Math.min(0.42, speed * 0.28)
  ) {
    frontBlocked = true;
  }

  if (
    rays[1] < 0.98 &&
    centerRange < 3.0
  ) {
    frontBlocked = true;
  }

  if (
    rays[3] < 0.98 &&
    centerRange < 3.0
  ) {
    frontBlocked = true;
  }

  const hardFront =
    centerRange <
      1.04 + Math.min(0.16, speed * 0.12) ||
    frontRisk < 0.82 ||
    (
      rays[1] < 0.62 &&
      centerRange < 2.45
    ) ||
    (
      rays[3] < 0.62 &&
      centerRange < 2.45
    );

  const rightAsym =
    rightNear + 0.22 < leftNear &&
    rightNear < 1.55;

  const leftAsym =
    leftNear + 0.22 < rightNear &&
    leftNear < 1.55;

  const sideClose =
    Math.min(rightNear, leftNear) <
      1.02 + Math.min(0.12, speed * 0.08);

  const hardSide =
    Math.min(rightNear, leftNear) < 0.56;

  const sideThreat =
    (
      !corridorLike &&
      (
        (
          rightAsym &&
          rightNear < 1.30 &&
          centerRange < 3.40
        ) ||
        (
          leftAsym &&
          leftNear < 1.30 &&
          centerRange < 3.40
        )
      )
    ) ||
    (
      corridorLike &&
      Math.abs(rightNear - leftNear) > 0.65 &&
      Math.min(rightNear, leftNear) < 1.0 &&
      centerRange < 3.0
    );

  const edge = 1.50;
  const edgeSpan = 1.20;

  let pushX = 0;
  let pushY = 0;

  if (x < edge) {
    pushX += clamp(
      (edge - x) / edgeSpan,
      0,
      1.6
    );
  }

  if (x > 40 - edge) {
    pushX -= clamp(
      (x - (40 - edge)) / edgeSpan,
      0,
      1.6
    );
  }

  if (y < edge) {
    pushY += clamp(
      (edge - y) / edgeSpan,
      0,
      1.6
    );
  }

  if (y > 40 - edge) {
    pushY -= clamp(
      (y - (40 - edge)) / edgeSpan,
      0,
      1.6
    );
  }

  const pushMagnitude = Math.hypot(
    pushX,
    pushY
  );

  let boundaryRel = 0;
  let inwardDot = 1;
  let boundarySteer = 0;

  if (pushMagnitude > 0.001) {
    const inwardBearing =
      Math.atan2(pushY, pushX) / DEG;

    boundaryRel = wrap(
      inwardBearing - navHeading
    );

    inwardDot = Math.cos(
      boundaryRel * DEG
    );

    boundarySteer =
      0.65 *
      clamp(boundaryRel / 90, -1, 1) *
      clamp(
        0.45 + pushMagnitude,
        0.45,
        1.30
      );
  }

  let boundaryCap = 1;

  if (
    pushMagnitude > 0.40 &&
    inwardDot < 0.60
  ) {
    boundaryCap = 0.68;
  }

  if (
    pushMagnitude > 0.78 &&
    inwardDot < 0.35
  ) {
    boundaryCap = 0.34;
  }

  if (
    pushMagnitude > 1.08 &&
    inwardDot < 0.10
  ) {
    boundaryCap = 0.10;
  }

  const boundaryThreat =
    (
      pushMagnitude > 0.28 &&
      inwardDot < 0.42
    ) ||
    x < 0.88 ||
    x > 39.12 ||
    y < 0.88 ||
    y > 39.12;

  const hardBoundary =
    x < 0.45 ||
    x > 39.55 ||
    y < 0.45 ||
    y > 39.55;

  function danger(q, limit) {
    if (q >= limit) return 0;

    return clamp(
      (limit - q) /
        Math.max(0.25, limit - 0.45),
      0,
      1
    );
  }

  const rightDanger = danger(
    rightNear,
    1.50
  );

  const leftDanger = danger(
    leftNear,
    1.50
  );

  function clearanceAt(angle) {
    angle = clamp(angle, -60, 60);

    if (angle <= -30) {
      const u = (angle + 60) / 30;
      return rays[0] * (1 - u) +
        rays[1] * u;
    }

    if (angle <= 0) {
      const u = (angle + 30) / 30;
      return rays[1] * (1 - u) +
        rays[2] * u;
    }

    if (angle <= 30) {
      const u = angle / 30;
      return rays[2] * (1 - u) +
        rays[3] * u;
    }

    const u = (angle - 30) / 30;
    return rays[3] * (1 - u) +
      rays[4] * u;
  }

  function sideOpening(side) {
    if (side > 0) {
      return Math.min(
        rays[3],
        rays[4]
      );
    }

    return Math.min(
      rays[1],
      rays[0]
    );
  }

  function chooseTurnSide() {
    if (
      boundaryThreat &&
      Math.abs(boundaryRel) > 18
    ) {
      return boundaryRel > 0 ? 1 : -1;
    }

    if (
      rightAsym &&
      !leftAsym
    ) {
      return 1;
    }

    if (
      leftAsym &&
      !rightAsym
    ) {
      return -1;
    }

    const leftOpen = sideOpening(1);
    const rightOpen = sideOpening(-1);

    if (
      targetBearing > 25 &&
      leftOpen >= rightOpen * 0.60 &&
      leftOpen > 0.90
    ) {
      return 1;
    }

    if (
      targetBearing < -25 &&
      rightOpen >= leftOpen * 0.60 &&
      rightOpen > 0.90
    ) {
      return -1;
    }

    if (leftOpen > rightOpen + 0.22) {
      return 1;
    }

    if (rightOpen > leftOpen + 0.22) {
      return -1;
    }

    return mem._v5SideBias >= 0 ? 1 : -1;
  }

  function drive(left, right, urgent, hard) {
    if (!finite(left)) left = 0;
    if (!finite(right)) right = 0;

    left = clamp(left, -1, 1);
    right = clamp(right, -1, 1);

    const baseStep = hard
      ? 0.34
      : (urgent ? 0.17 : 0.08);

    function moveCommand(oldValue, newValue) {
      let step = baseStep;

      if (newValue < oldValue) {
        step = Math.max(
          step,
          urgent ? 0.20 : 0.11
        );
      }

      if (newValue * oldValue < 0) {
        step = Math.max(
          step,
          hard ? 0.34 : 0.22
        );
      }

      return oldValue + clamp(
        newValue - oldValue,
        -step,
        step
      );
    }

    mem._v5CmdL = clamp(
      moveCommand(
        finite(mem._v5CmdL) ? mem._v5CmdL : 0,
        left
      ),
      -1,
      1
    );

    mem._v5CmdR = clamp(
      moveCommand(
        finite(mem._v5CmdR) ? mem._v5CmdR : 0,
        right
      ),
      -1,
      1
    );

    return {
      left: mem._v5CmdL,
      right: mem._v5CmdR
    };
  }

  function beginAvoid(side) {
    side = side >= 0 ? 1 : -1;

    mem._v5Mode = 1;
    mem._v5TurnSide = side;
    mem._v5WallSide = -side;
    mem._v5AvoidStart = now;
    mem._v5HitDist = Math.max(
      targetDistance,
      0.80
    );
    mem._v5BestDist = targetDistance;
    mem._v5LastProgress = now;
    mem._v5ClearSince = 0;
    mem._v5SideBias = -side;
  }

  function beginRecovery(side) {
    if (side !== 1 && side !== -1) {
      side = chooseTurnSide();
    }

    if (
      mem._v5RecoverCount % 2 === 1 &&
      side === mem._v5TurnSide
    ) {
      side = -side;
    }

    mem._v5Mode = 2;
    mem._v5RecoverStart = now;
    mem._v5RecoverTurn = side;
    mem._v5RecoverCount += 1;
    mem._v5Stall = 0;
  }

  function targetPathClear() {
    if (Math.abs(targetBearing) > 70) {
      return false;
    }

    const a = clamp(
      targetBearing,
      -60,
      60
    );

    const c0 = clearanceAt(a);
    const c1 = clearanceAt(
      clamp(a - 12, -60, 60)
    );
    const c2 = clearanceAt(
      clamp(a + 12, -60, 60)
    );

    return (
      Math.min(c0, c1, c2) >
        1.35 + Math.min(0.30, speed * 0.18) &&
      frontRisk > 1.25 &&
      !frontBlocked &&
      !hardFront &&
      !hardSide &&
      !boundaryThreat &&
      !hardBoundary &&
      !sideThreat
    );
  }

  if (!hasTarget) {
    return drive(0, 0, true, false);
  }

  if (targetDistance < 0.68) {
    return drive(0, 0, true, false);
  }

  if (mem._v5Mode === 2) {
    const phase = now - mem._v5RecoverStart;
    const side =
      mem._v5RecoverTurn >= 0 ? 1 : -1;

    if (phase < 0.12) {
      return drive(0, 0, true, false);
    }

    if (phase < 0.42) {
      return drive(
        -0.24,
        -0.24,
        true,
        false
      );
    }

    if (phase < 1.42) {
      return drive(
        -0.58 * side,
        0.58 * side,
        true,
        true
      );
    }

    mem._v5Mode = 1;
    mem._v5TurnSide = side;
    mem._v5WallSide = -side;
    mem._v5AvoidStart = now;
    mem._v5HitDist = Math.max(
      targetDistance,
      0.80
    );
    mem._v5BestDist = targetDistance;
    mem._v5LastProgress = now;
    mem._v5ClearSince = 0;
    mem._v5SideBias = -side;
  }

  const hazard =
    frontBlocked ||
    sideThreat ||
    hardSide ||
    boundaryThreat ||
    hardBoundary;

  if (
    mem._v5Mode === 0 &&
    targetDistance > 0.76 &&
    hazard
  ) {
    beginAvoid(chooseTurnSide());
  }

  if (
    mem._v5Mode === 0 &&
    mem._v5Stall > 1.20 &&
    targetDistance > 1.0
  ) {
    beginRecovery(chooseTurnSide());
    return drive(0, 0, true, false);
  }

  if (mem._v5Mode === 1) {
    if (
      targetDistance <
      mem._v5BestDist - 0.05
    ) {
      mem._v5BestDist = targetDistance;
      mem._v5LastProgress = now;
    }

    const elapsed =
      now - mem._v5AvoidStart;

    const progressNeeded = clamp(
      0.42 +
        0.025 *
        Math.min(mem._v5HitDist, 20),
      0.45,
      0.95
    );

    const madeProgress =
      targetDistance <
      mem._v5HitDist - progressNeeded;

    const weakProgress =
      elapsed > 2.2 &&
      targetDistance <
        mem._v5HitDist - 0.22;

    if (
      elapsed > 1.0 &&
      (
        madeProgress ||
        weakProgress
      ) &&
      targetPathClear()
    ) {
      if (!mem._v5ClearSince) {
        mem._v5ClearSince = now;
      }
    } else {
      mem._v5ClearSince = 0;
    }

    if (
      elapsed > 1.0 &&
      mem._v5ClearSince > 0 &&
      now - mem._v5ClearSince > 0.45
    ) {
      mem._v5Mode = 0;
      mem._v5ClearSince = 0;
    }

    if (mem._v5Mode === 1) {
      const noProgress =
        elapsed > 4.0 &&
        now - mem._v5LastProgress > 8.5;

      if (
        noProgress ||
        elapsed > 24.0
      ) {
        let recoverySide = chooseTurnSide();

        if (
          recoverySide === mem._v5TurnSide
        ) {
          recoverySide = -recoverySide;
        }

        beginRecovery(recoverySide);
        return drive(0, 0, true, false);
      }
    }
  }

  if (mem._v5Mode === 1) {
    let turnSide =
      mem._v5TurnSide >= 0 ? 1 : -1;

    if (
      hardFront &&
      now - mem._v5AvoidStart > 0.55
    ) {
      const selected = sideOpening(turnSide);
      const alternate = sideOpening(-turnSide);

      if (
        selected < 0.92 &&
        alternate > selected + 0.25
      ) {
        turnSide = -turnSide;
        mem._v5TurnSide = turnSide;
        mem._v5WallSide = -turnSide;
      }
    }

    const wallSide =
      mem._v5WallSide < 0 ? -1 : 1;

    const wallDistance = wallSide < 0
      ? 0.58 * rays[1] + 0.42 * rays[0]
      : 0.58 * rays[3] + 0.42 * rays[4];

    let steer = 0;

    const wallError = clamp(
      (wallDistance - 0.95) / 1.20,
      -0.65,
      0.65
    );

    steer +=
      wallSide *
      wallError *
      0.52;

    const elapsed =
      now - mem._v5AvoidStart;

    if (elapsed < 0.90) {
      steer +=
        turnSide *
        (
          0.34 *
          (1 - elapsed / 0.90) +
          0.08
        );
    }

    if (centerRange < dynamicFront) {
      steer +=
        turnSide *
        (
          0.22 +
          0.58 *
          danger(centerRange, dynamicFront)
        );
    } else if (
      !corridorSafe &&
      frontRisk < 2.55
    ) {
      steer +=
        turnSide *
        0.16 *
        danger(frontRisk, 2.55);
    }

    if (!corridorLike) {
      steer +=
        0.28 *
        (rightDanger - leftDanger);

      steer +=
        0.10 *
        (
          danger(rays[1], 1.65) -
          danger(rays[3], 1.65)
        );
    } else {
      steer +=
        0.22 *
        clamp(
          (leftNear - rightNear) / 1.20,
          -1,
          1
        );
    }

    steer +=
      0.045 *
      clamp(targetBearing / 100, -1, 1);

    steer += boundarySteer;

    steer -= clamp(
      mem._v5HeadingRate * 0.0018,
      -0.20,
      0.20
    );

    if (narrowCorridor) {
      steer = clamp(
        steer,
        -0.48,
        0.48
      );
    } else {
      steer = clamp(
        steer,
        -0.88,
        0.88
      );
    }

    let base = 0.42;

    if (elapsed < 0.60) {
      base = 0.25;
    }

    if (frontRisk < 2.55) {
      base = Math.min(base, 0.31);
    }

    if (frontRisk < 2.05) {
      base = Math.min(base, 0.22);
    }

    if (frontRisk < 1.55) {
      base = Math.min(base, 0.10);
    }

    if (frontRisk < 1.12) {
      base = Math.min(base, 0.025);
    }

    if (sideClose) {
      base *= 0.72;
    }

    if (corridorLike) {
      base = Math.min(base, 0.30);
    }

    if (narrowCorridor) {
      base = Math.min(base, 0.18);
    }

    if (wallDistance < 0.60) {
      base *= 0.62;
    }

    if (targetDistance < 4.5) {
      base *= clamp(
        0.46 + targetDistance * 0.11,
        0.46,
        1
      );
    }

    if (speed > 1.20) {
      base *= 0.82;
    }

    if (speed > 1.65) {
      base *= 0.64;
    }

    base = Math.min(
      base,
      boundaryCap
    );

    if (Math.abs(steer) > 0.55) {
      base = Math.min(base, 0.18);
    }

    if (Math.abs(steer) > 0.75) {
      base = Math.min(base, 0.08);
    }

    let hardNow = false;

    if (
      hardBoundary ||
      hardFront ||
      hardSide
    ) {
      let emergencySide = turnSide;

      if (hardBoundary) {
        emergencySide =
          boundaryRel >= 0 ? 1 : -1;
      } else if (
        hardSide &&
        !hardFront
      ) {
        emergencySide = rightNear < leftNear
          ? 1
          : -1;
      }

      base = speed > 0.28
        ? -0.08
        : 0;

      steer =
        emergencySide * 0.88 -
        clamp(
          mem._v5HeadingRate * 0.0008,
          -0.12,
          0.12
        );

      hardNow = true;
    }

    const urgent =
      frontBlocked ||
      sideThreat ||
      sideClose ||
      boundaryThreat ||
      hardBoundary ||
      hardFront ||
      hardSide;

    return drive(
      base - steer,
      base + steer,
      urgent,
      hardNow
    );
  }

  const targetAngle = Math.abs(
    targetBearing
  );

  let base;

  if (targetAngle > 135) {
    base = 0.01;
  } else if (targetAngle > 110) {
    base = 0.055;
  } else if (targetAngle > 85) {
    base = 0.14;
  } else if (targetAngle > 60) {
    base = 0.30;
  } else if (targetAngle > 35) {
    base = 0.50;
  } else {
    base = 0.68;
  }

  if (targetDistance < 4.5) {
    base *= clamp(
      0.50 + targetDistance * 0.11,
      0.50,
      1
    );
  }

  if (targetDistance < 1.45) {
    base = Math.min(base, 0.18);
  }

  if (targetDistance < 0.95) {
    base = Math.min(base, 0.105);
  }

  if (speed > 1.28) {
    base *= 0.82;
  }

  if (speed > 1.70) {
    base *= 0.64;
  }

  let steer =
    0.40 *
    clamp(
      targetBearing / 72,
      -1,
      1
    );

  if (targetAngle > 108) {
    steer =
      0.54 *
      (targetBearing >= 0 ? 1 : -1);
  }

  steer -= clamp(
    mem._v5HeadingRate * 0.0026,
    -0.23,
    0.23
  );

  steer +=
    0.22 *
    (rightDanger - leftDanger);

  steer +=
    0.08 *
    (
      danger(rays[0], 1.25) -
      danger(rays[4], 1.25)
    );

  if (corridorLike) {
    steer *= 0.52;

    steer +=
      0.23 *
      clamp(
        (leftNear - rightNear) / 1.20,
        -1,
        1
      );

    base = Math.min(base, 0.31);

    if (narrowCorridor) {
      base = Math.min(base, 0.19);

      if (targetAngle > 65) {
        base = Math.min(base, 0.08);
      }

      steer = clamp(
        steer,
        -0.27,
        0.27
      );
    }
  } else if (sideThreat) {
    const side = chooseTurnSide();

    steer +=
      side *
      (
        0.16 +
        0.22 *
        danger(
          Math.min(rightNear, leftNear),
          1.45
        )
      );

    base = Math.min(base, 0.32);
  }

  if (frontRisk < 2.65) {
    base = Math.min(base, 0.48);
  }

  if (frontRisk < 2.05) {
    base = Math.min(base, 0.32);
  }

  if (frontRisk < 1.60) {
    base = Math.min(base, 0.18);
  }

  if (frontRisk < 1.20) {
    base = Math.min(base, 0.07);
  }

  if (sideClose) {
    base *= corridorLike ? 0.78 : 0.72;
  }

  steer += boundarySteer;

  steer = clamp(
    steer,
    -0.82,
    0.82
  );

  base = Math.min(
    base,
    boundaryCap
  );

  if (Math.abs(steer) > 0.58) {
    base = Math.min(base, 0.19);
  }

  if (Math.abs(steer) > 0.76) {
    base = Math.min(base, 0.08);
  }

  const urgent =
    sideClose ||
    sideThreat ||
    frontRisk < 1.95 ||
    boundaryThreat ||
    hardBoundary ||
    targetAngle > 112;

  return drive(
    base - steer,
    base + steer,
    urgent,
    false
  );
}

function act(obs, mem) {
  obs = obs || {};
  mem = mem || {};

  const finite = (v) =>
    typeof v === "number" && Number.isFinite(v);

  const clamp = (v, lo, hi) =>
    Math.max(lo, Math.min(hi, v));

  const DEG = Math.PI / 180;

  function wrap(a) {
    while (a > 180) a -= 360;
    while (a < -180) a += 360;
    return a;
  }

  let now = finite(obs.t)
    ? obs.t
    : (finite(mem._s6LastT) ? mem._s6LastT + 0.05 : 0.05);

  let targetIndex = finite(obs.targetIndex)
    ? Math.max(0, Math.floor(obs.targetIndex))
    : (finite(mem._s6TargetIndex)
      ? mem._s6TargetIndex
      : 0);

  let targetX = finite(obs.targetX) ? obs.targetX : NaN;
  let targetY = finite(obs.targetY) ? obs.targetY : NaN;

  if (
    !(finite(targetX) && finite(targetY)) &&
    Array.isArray(obs.targets)
  ) {
    const item = obs.targets[targetIndex];

    if (Array.isArray(item) && item.length >= 2) {
      if (!finite(targetX) && finite(item[0])) {
        targetX = item[0];
      }

      if (!finite(targetY) && finite(item[1])) {
        targetY = item[1];
      }
    } else if (item && typeof item === "object") {
      if (!finite(targetX) && finite(item.x)) {
        targetX = item.x;
      }

      if (!finite(targetY) && finite(item.y)) {
        targetY = item.y;
      }
    }

    if (
      (!finite(targetX) || !finite(targetY)) &&
      finite(obs.targets[targetIndex * 2]) &&
      finite(obs.targets[targetIndex * 2 + 1])
    ) {
      targetX = obs.targets[targetIndex * 2];
      targetY = obs.targets[targetIndex * 2 + 1];
    }
  }

  if (!finite(targetX) && finite(obs.goalX)) {
    targetX = obs.goalX;
  }

  if (!finite(targetY) && finite(obs.goalY)) {
    targetY = obs.goalY;
  }

  const hasTarget =
    finite(targetX) &&
    finite(targetY);

  if (
    mem._s6Init &&
    finite(mem._s6LastT) &&
    now < mem._s6LastT - 0.5
  ) {
    mem._s6Init = false;
  }

  const initialX = finite(obs.x) ? obs.x : 20;
  const initialY = finite(obs.y) ? obs.y : 20;
  const initialHeading = finite(obs.heading)
    ? wrap(obs.heading)
    : 0;

  if (!mem._s6Init) {
    mem._s6Init = true;

    mem._s6Mode = 0;
    mem._s6TargetIndex = targetIndex;
    mem._s6LastTargetX = hasTarget ? targetX : NaN;
    mem._s6LastTargetY = hasTarget ? targetY : NaN;

    mem._s6PrevX = initialX;
    mem._s6PrevY = initialY;
    mem._s6LastHeading = initialHeading;
    mem._s6LastT = now;

    mem._s6CmdL = 0;
    mem._s6CmdR = 0;
    mem._s6SteerFilt = 0;

    mem._s6HeadingOffset = 0;
    mem._s6HeadingRate = 0;

    mem._s6SampleX = initialX;
    mem._s6SampleY = initialY;
    mem._s6SampleT = now;
    mem._s6CourseValid = false;
    mem._s6Course = initialHeading;

    mem._s6RayFilter = null;

    mem._s6Stall = 0;
    mem._s6SideBias = 1;

    mem._s6TurnSide = 1;
    mem._s6WallSide = -1;

    mem._s6AvoidStart = now;
    mem._s6HitDist = 1e9;
    mem._s6BestDist = 1e9;
    mem._s6LastProgress = now;
    mem._s6ClearSince = 0;
    mem._s6LeaveUntil = 0;
    mem._s6LastSwitch = now;

    mem._s6RecoverStart = 0;
    mem._s6RecoverTurn = 1;
    mem._s6RecoverCount = 0;
  }

  let dt = now - mem._s6LastT;

  if (
    !finite(dt) ||
    dt <= 0 ||
    dt > 0.5
  ) {
    dt = 0.05;
  }

  const x = finite(obs.x)
    ? obs.x
    : mem._s6PrevX;

  const y = finite(obs.y)
    ? obs.y
    : mem._s6PrevY;

  const heading = finite(obs.heading)
    ? wrap(obs.heading)
    : wrap(mem._s6LastHeading);

  const moved = Math.hypot(
    x - mem._s6PrevX,
    y - mem._s6PrevY
  );

  const speed = finite(obs.speed)
    ? Math.abs(obs.speed)
    : clamp(
        moved / Math.max(0.05, dt),
        0,
        3
      );

  const previousL = finite(mem._s6CmdL)
    ? mem._s6CmdL
    : 0;

  const previousR = finite(mem._s6CmdR)
    ? mem._s6CmdR
    : 0;

  const previousForward =
    (previousL + previousR) * 0.5;

  const previousSteer =
    (previousR - previousL) * 0.5;

  if (
    previousForward > 0.28 &&
    speed < 0.16 &&
    moved < 0.04
  ) {
    mem._s6Stall += dt;
  } else {
    mem._s6Stall = Math.max(
      0,
      mem._s6Stall - dt * 1.2
    );
  }

  let headingDelta = wrap(
    heading - mem._s6LastHeading
  );

  headingDelta = clamp(
    headingDelta,
    -120,
    120
  );

  const instantRate =
    headingDelta / Math.max(0.01, dt);

  mem._s6HeadingRate =
    0.82 * (
      finite(mem._s6HeadingRate)
        ? mem._s6HeadingRate
        : 0
    ) +
    0.18 * clamp(
      instantRate,
      -260,
      260
    );

  if (
    now - mem._s6SampleT >= 0.35
  ) {
    const dx = x - mem._s6SampleX;
    const dy = y - mem._s6SampleY;
    const courseLength = Math.hypot(dx, dy);

    if (courseLength > 0.18) {
      const course =
        Math.atan2(dy, dx) / DEG;

      mem._s6Course = course;
      mem._s6CourseValid = true;

      if (
        previousForward > 0.34 &&
        Math.abs(previousSteer) < 0.10 &&
        speed > 0.30 &&
        Math.abs(mem._s6HeadingRate) < 48
      ) {
        const courseError = wrap(
          course - heading
        );

        if (Math.abs(courseError) < 45) {
          mem._s6HeadingOffset = clamp(
            0.97 * mem._s6HeadingOffset +
              0.03 * courseError,
            -35,
            35
          );
        }
      }
    }

    mem._s6SampleX = x;
    mem._s6SampleY = y;
    mem._s6SampleT = now;
  }

  const oldHasTarget =
    finite(mem._s6LastTargetX) &&
    finite(mem._s6LastTargetY);

  const targetChanged =
    targetIndex !== mem._s6TargetIndex ||
    hasTarget !== oldHasTarget ||
    (
      hasTarget &&
      oldHasTarget &&
      Math.hypot(
        targetX - mem._s6LastTargetX,
        targetY - mem._s6LastTargetY
      ) > 1.0
    );

  const targetDistance = hasTarget
    ? Math.hypot(
        targetX - x,
        targetY - y
      )
    : 1e9;

  if (targetChanged) {
    mem._s6TargetIndex = targetIndex;
    mem._s6LastTargetX = hasTarget ? targetX : NaN;
    mem._s6LastTargetY = hasTarget ? targetY : NaN;

    mem._s6Mode = 0;
    mem._s6Stall = 0;
    mem._s6AvoidStart = now;
    mem._s6HitDist = targetDistance;
    mem._s6BestDist = targetDistance;
    mem._s6LastProgress = now;
    mem._s6ClearSince = 0;
    mem._s6LeaveUntil = 0;
  }

  mem._s6PrevX = x;
  mem._s6PrevY = y;
  mem._s6LastHeading = heading;
  mem._s6LastT = now;

  const rawRays = new Array(5);

  for (let i = 0; i < 5; i++) {
    let q =
      obs.rays &&
      finite(obs.rays[i])
        ? obs.rays[i]
        : 10;

    rawRays[i] = clamp(q, 0, 10);
  }

  if (finite(obs.distanceAhead)) {
    rawRays[2] = Math.min(
      rawRays[2],
      clamp(obs.distanceAhead, 0, 10)
    );
  }

  if (
    !Array.isArray(mem._s6RayFilter) ||
    mem._s6RayFilter.length !== 5
  ) {
    mem._s6RayFilter = rawRays.slice();
  } else {
    for (let i = 0; i < 5; i++) {
      const alpha =
        rawRays[i] < mem._s6RayFilter[i]
          ? 0.74
          : 0.24;

      mem._s6RayFilter[i] +=
        alpha * (
          rawRays[i] - mem._s6RayFilter[i]
        );
    }
  }

  const rays = new Array(5);

  for (let i = 0; i < 5; i++) {
    rays[i] = Math.min(
      rawRays[i],
      mem._s6RayFilter[i]
    );
  }

  const navHeading = wrap(
    heading + mem._s6HeadingOffset
  );

  const globalTargetBearing = hasTarget
    ? Math.atan2(
        targetY - y,
        targetX - x
      ) / DEG
    : 0;

  const targetBearing = wrap(
    globalTargetBearing - navHeading
  );

  const targetAngle = Math.abs(
    targetBearing
  );

  const rightNear = Math.min(
    rays[0],
    rays[1]
  );

  const leftNear = Math.min(
    rays[3],
    rays[4]
  );

  const centerRange = rays[2];

  const corridorLike =
    centerRange > 1.75 &&
    rightNear < 1.75 &&
    leftNear < 1.75 &&
    Math.abs(rightNear - leftNear) < 0.85;

  const narrowCorridor =
    corridorLike &&
    Math.min(rightNear, leftNear) < 0.92;

  const corridorSafe =
    corridorLike &&
    centerRange > 2.15 &&
    rays[1] > 0.68 &&
    rays[3] > 0.68;

  const frontLimit =
    1.55 +
    Math.min(
      0.58,
      speed * 0.40
    );

  const frontRisk = Math.min(
    centerRange,
    rays[1] + 0.38,
    rays[3] + 0.38,
    rays[0] + 0.68,
    rays[4] + 0.68
  );

  const forwardClear =
    corridorSafe
      ? centerRange
      : frontRisk;

  let frontBlocked =
    centerRange < frontLimit;

  if (
    corridorSafe &&
    centerRange > 1.85
  ) {
    frontBlocked = false;
  }

  if (
    !corridorSafe &&
    frontRisk <
      1.28 +
      Math.min(0.30, speed * 0.22)
  ) {
    frontBlocked = true;
  }

  const hardFront =
    centerRange < 0.78 ||
    (
      !corridorLike &&
      frontRisk < 0.68
    ) ||
    (
      !corridorLike &&
      rays[1] < 0.48 &&
      centerRange < 1.75
    ) ||
    (
      !corridorLike &&
      rays[3] < 0.48 &&
      centerRange < 1.75
    );

  const rightAsym =
    rightNear + 0.24 < leftNear &&
    rightNear < 1.60;

  const leftAsym =
    leftNear + 0.24 < rightNear &&
    leftNear < 1.60;

  const sideClose =
    Math.min(rightNear, leftNear) <
    0.78 + Math.min(0.10, speed * 0.05);

  const hardSide =
    (
      !corridorLike &&
      Math.min(rightNear, leftNear) < 0.43
    ) ||
    (
      Math.min(rightNear, leftNear) < 0.36
    );

  const sideThreat =
    (
      !corridorLike &&
      (
        (
          rightAsym &&
          rightNear < 1.28 &&
          centerRange < 3.40
        ) ||
        (
          leftAsym &&
          leftNear < 1.28 &&
          centerRange < 3.40
        )
      )
    ) ||
    (
      corridorLike &&
      Math.abs(rightNear - leftNear) > 0.58 &&
      Math.min(rightNear, leftNear) < 0.86 &&
      centerRange < 3.0
    );

  const edge = 1.25;
  const edgeSpan = 1.05;

  let pushX = 0;
  let pushY = 0;

  if (x < edge) {
    pushX += clamp(
      (edge - x) / edgeSpan,
      0,
      1.6
    );
  }

  if (x > 40 - edge) {
    pushX -= clamp(
      (x - (40 - edge)) / edgeSpan,
      0,
      1.6
    );
  }

  if (y < edge) {
    pushY += clamp(
      (edge - y) / edgeSpan,
      0,
      1.6
    );
  }

  if (y > 40 - edge) {
    pushY -= clamp(
      (y - (40 - edge)) / edgeSpan,
      0,
      1.6
    );
  }

  const pushMagnitude = Math.hypot(
    pushX,
    pushY
  );

  let boundaryRel = 0;
  let inwardDot = 1;
  let boundarySteer = 0;

  if (pushMagnitude > 0.001) {
    const inwardBearing =
      Math.atan2(pushY, pushX) / DEG;

    boundaryRel = wrap(
      inwardBearing - navHeading
    );

    inwardDot = Math.cos(
      boundaryRel * DEG
    );

    boundarySteer =
      0.56 *
      clamp(boundaryRel / 90, -1, 1) *
      clamp(
        0.42 + pushMagnitude,
        0.42,
        1.30
      );
  }

  let boundaryCap = 1;

  if (
    pushMagnitude > 0.38 &&
    inwardDot < 0.60
  ) {
    boundaryCap = 0.70;
  }

  if (
    pushMagnitude > 0.78 &&
    inwardDot < 0.35
  ) {
    boundaryCap = 0.35;
  }

  if (
    pushMagnitude > 1.08 &&
    inwardDot < 0.10
  ) {
    boundaryCap = 0.10;
  }

  const boundaryThreat =
    (
      pushMagnitude > 0.25 &&
      inwardDot < 0.45
    ) ||
    x < 0.82 ||
    x > 39.18 ||
    y < 0.82 ||
    y > 39.18;

  const hardBoundary =
    x < 0.48 ||
    x > 39.52 ||
    y < 0.48 ||
    y > 39.52;

  function danger(q, limit) {
    if (q >= limit) return 0;

    return clamp(
      (limit - q) /
        Math.max(0.25, limit - 0.35),
      0,
      1
    );
  }

  const rightDanger = danger(
    rightNear,
    1.50
  );

  const leftDanger = danger(
    leftNear,
    1.50
  );

  function clearanceAt(angle) {
    angle = clamp(angle, -60, 60);

    if (angle <= -30) {
      const u = (angle + 60) / 30;
      return rays[0] * (1 - u) +
        rays[1] * u;
    }

    if (angle <= 0) {
      const u = (angle + 30) / 30;
      return rays[1] * (1 - u) +
        rays[2] * u;
    }

    if (angle <= 30) {
      const u = angle / 30;
      return rays[2] * (1 - u) +
        rays[3] * u;
    }

    const u = (angle - 30) / 30;
    return rays[3] * (1 - u) +
      rays[4] * u;
  }

  function sideOpening(side) {
    if (side > 0) {
      return 0.70 * rays[3] +
        0.30 * rays[4];
    }

    return 0.70 * rays[1] +
      0.30 * rays[0];
  }

  function chooseTurnSide() {
    if (
      boundaryThreat &&
      Math.abs(boundaryRel) > 18
    ) {
      return boundaryRel >= 0 ? 1 : -1;
    }

    if (
      rightAsym &&
      !leftAsym
    ) {
      return 1;
    }

    if (
      leftAsym &&
      !rightAsym
    ) {
      return -1;
    }

    const leftOpen = sideOpening(1);
    const rightOpen = sideOpening(-1);

    if (
      targetBearing > 20 &&
      leftOpen > 0.78 &&
      leftOpen >= rightOpen * 0.58
    ) {
      return 1;
    }

    if (
      targetBearing < -20 &&
      rightOpen > 0.78 &&
      rightOpen >= leftOpen * 0.58
    ) {
      return -1;
    }

    if (leftOpen > rightOpen + 0.22) {
      return 1;
    }

    if (rightOpen > leftOpen + 0.22) {
      return -1;
    }

    return mem._s6SideBias >= 0 ? 1 : -1;
  }

  function targetPathClear() {
    if (Math.abs(targetBearing) > 75) {
      return false;
    }

    const a = clamp(
      targetBearing,
      -60,
      60
    );

    const c0 = clearanceAt(a);
    const c1 = clearanceAt(
      clamp(a - 10, -60, 60)
    );
    const c2 = clearanceAt(
      clamp(a + 10, -60, 60)
    );

    const pathLimit =
      corridorLike ? 0.68 : 1.15;

    return (
      Math.min(c0, c1, c2) >
        pathLimit &&
      (
        corridorSafe ||
        forwardClear > 1.25
      ) &&
      !hardFront &&
      !hardSide &&
      !boundaryThreat &&
      !hardBoundary &&
      !sideThreat
    );
  }

  function driveBS(base, steer, urgent, hard) {
    if (!finite(base)) base = 0;
    if (!finite(steer)) steer = 0;

    base = clamp(base, -1, 1);
    steer = clamp(steer, -0.95, 0.95);

    if (hard) {
      mem._s6SteerFilt = steer;
    } else {
      const alpha = urgent ? 0.34 : 0.20;

      if (!finite(mem._s6SteerFilt)) {
        mem._s6SteerFilt = steer;
      } else {
        mem._s6SteerFilt +=
          alpha * (
            steer - mem._s6SteerFilt
          );
      }

      steer = mem._s6SteerFilt;
    }

    let desiredL = clamp(
      base - steer,
      -1,
      1
    );

    let desiredR = clamp(
      base + steer,
      -1,
      1
    );

    const oldL = finite(mem._s6CmdL)
      ? mem._s6CmdL
      : 0;

    const oldR = finite(mem._s6CmdR)
      ? mem._s6CmdR
      : 0;

    let step = hard
      ? 0.28
      : (urgent ? 0.11 : 0.05);

    function slew(oldValue, newValue) {
      let localStep = step;

      if (newValue < oldValue) {
        localStep = Math.max(
          localStep,
          urgent ? 0.14 : 0.065
        );
      }

      if (newValue * oldValue < 0) {
        localStep = Math.max(
          localStep,
          hard ? 0.30 : (urgent ? 0.17 : 0.085)
        );
      }

      return oldValue + clamp(
        newValue - oldValue,
        -localStep,
        localStep
      );
    }

    mem._s6CmdL = clamp(
      slew(oldL, desiredL),
      -1,
      1
    );

    mem._s6CmdR = clamp(
      slew(oldR, desiredR),
      -1,
      1
    );

    return {
      left: mem._s6CmdL,
      right: mem._s6CmdR
    };
  }

  function beginAvoid(side) {
    side = side >= 0 ? 1 : -1;

    mem._s6Mode = 1;
    mem._s6TurnSide = side;
    mem._s6WallSide = -side;
    mem._s6AvoidStart = now;
    mem._s6HitDist = Math.max(
      targetDistance,
      0.80
    );
    mem._s6BestDist = targetDistance;
    mem._s6LastProgress = now;
    mem._s6ClearSince = 0;
    mem._s6LastSwitch = now;
    mem._s6LeaveUntil = now + 0.95;
    mem._s6SideBias = -side;
  }

  function beginRecovery(side) {
    if (side !== 1 && side !== -1) {
      side = chooseTurnSide();
    }

    if (
      mem._s6RecoverCount % 2 === 1 &&
      side === mem._s6TurnSide
    ) {
      side = -side;
    }

    mem._s6Mode = 2;
    mem._s6RecoverStart = now;
    mem._s6RecoverTurn = side;
    mem._s6RecoverCount += 1;
    mem._s6Stall = 0;
  }

  if (!hasTarget) {
    return driveBS(
      0,
      0,
      true,
      false
    );
  }

  if (targetDistance < 0.72) {
    return driveBS(
      0,
      0,
      true,
      false
    );
  }

  if (mem._s6Mode === 2) {
    const phase =
      now - mem._s6RecoverStart;

    const side =
      mem._s6RecoverTurn >= 0 ? 1 : -1;

    if (phase < 0.14) {
      return driveBS(
        0,
        0,
        true,
        false
      );
    }

    if (phase < 0.46) {
      return driveBS(
        -0.18,
        0,
        true,
        false
      );
    }

    if (phase < 1.22) {
      return driveBS(
        -0.04,
        0.40 * side,
        true,
        true
      );
    }

    mem._s6Mode = 1;
    mem._s6TurnSide = side;
    mem._s6WallSide = -side;
    mem._s6AvoidStart = now;
    mem._s6HitDist = Math.max(
      targetDistance,
      0.80
    );
    mem._s6BestDist = targetDistance;
    mem._s6LastProgress = now;
    mem._s6ClearSince = 0;
    mem._s6LastSwitch = now;
    mem._s6LeaveUntil = now + 0.75;
    mem._s6SideBias = -side;
  }

  const hazard =
    frontBlocked ||
    sideThreat ||
    hardSide ||
    boundaryThreat ||
    hardBoundary;

  if (
    mem._s6Mode === 0 &&
    targetDistance > 0.80 &&
    hazard &&
    (
      now >= mem._s6LeaveUntil ||
      hardFront ||
      hardSide ||
      hardBoundary
    )
  ) {
    beginAvoid(
      chooseTurnSide()
    );
  }

  if (
    mem._s6Mode === 0 &&
    mem._s6Stall > 1.55 &&
    targetDistance > 1.0
  ) {
    beginRecovery(
      chooseTurnSide()
    );

    return driveBS(
      0,
      0,
      true,
      false
    );
  }

  if (mem._s6Mode === 1) {
    if (
      targetDistance <
      mem._s6BestDist - 0.06
    ) {
      mem._s6BestDist = targetDistance;
      mem._s6LastProgress = now;
    }

    const elapsed =
      now - mem._s6AvoidStart;

    const progressNeeded = clamp(
      0.34 +
        0.025 *
        Math.min(mem._s6HitDist, 18),
      0.38,
      0.82
    );

    const madeProgress =
      targetDistance <
      mem._s6HitDist - progressNeeded;

    if (
      elapsed > 1.10 &&
      (
        madeProgress ||
        targetDistance < 0.90
      ) &&
      targetPathClear()
    ) {
      if (!mem._s6ClearSince) {
        mem._s6ClearSince = now;
      }
    } else {
      mem._s6ClearSince = 0;
    }

    if (
      mem._s6ClearSince > 0 &&
      now - mem._s6ClearSince > 0.38
    ) {
      mem._s6Mode = 0;
      mem._s6LeaveUntil = now + 0.62;
      mem._s6ClearSince = 0;
    }

    if (mem._s6Mode === 1) {
      const noProgress =
        elapsed > 4.5 &&
        now - mem._s6LastProgress > 6.8;

      if (
        noProgress ||
        elapsed > 18.0
      ) {
        let recoverySide =
          chooseTurnSide();

        if (
          recoverySide ===
          mem._s6TurnSide
        ) {
          recoverySide =
            -recoverySide;
        }

        beginRecovery(
          recoverySide
        );

        return driveBS(
          0,
          0,
          true,
          false
        );
      }
    }
  }

  if (mem._s6Mode === 1) {
    let turnSide =
      mem._s6TurnSide >= 0 ? 1 : -1;

    if (
      hardFront &&
      now - mem._s6LastSwitch > 0.80
    ) {
      const selected =
        sideOpening(turnSide);

      const alternate =
        sideOpening(-turnSide);

      if (
        selected < 0.86 &&
        alternate > selected + 0.24
      ) {
        turnSide = -turnSide;
        mem._s6TurnSide = turnSide;
        mem._s6WallSide = -turnSide;
        mem._s6LastSwitch = now;
      }
    }

    const wallSide =
      mem._s6WallSide < 0 ? -1 : 1;

    const wallDistance =
      wallSide < 0
        ? 0.64 * rays[1] +
          0.36 * rays[0]
        : 0.64 * rays[3] +
