    ? mem._v8CmdL
    : 0;

  const previousR = finite(mem._v8CmdR)
    ? mem._v8CmdR
    : 0;

  const previousForward =
    (previousL + previousR) * 0.5;

  const previousTurnAbs =
    Math.abs(previousR - previousL) * 0.5;

  if (
    previousForward > 0.30 &&
    speed < 0.18 &&
    moved < 0.035
  ) {
    mem._v8Stall += dt;
  } else {
    mem._v8Stall = Math.max(
      0,
      mem._v8Stall - dt * 1.3
    );
  }

  let headingDelta = wrap(
    heading - mem._v8LastHeading
  );

  headingDelta = clamp(
    headingDelta,
    -120,
    120
  );

  const instantRate =
    headingDelta / Math.max(0.01, dt);

  mem._v8HeadingRate =
    0.78 * (
      finite(mem._v8HeadingRate)
        ? mem._v8HeadingRate
        : 0
    ) +
    0.22 * clamp(
      instantRate,
      -300,
      300
    );

  if (
    now - mem._v8SampleT >= 0.32
  ) {
    const dx = x - mem._v8SampleX;
    const dy = y - mem._v8SampleY;
    const courseLength = Math.hypot(dx, dy);

    if (courseLength > 0.20) {
      const course =
        Math.atan2(dy, dx) / DEG;

      mem._v8Course = course;
      mem._v8CourseValid = true;

      if (
        previousForward > 0.34 &&
        previousTurnAbs < 0.11 &&
        speed > 0.25 &&
        Math.abs(mem._v8HeadingRate) < 50
      ) {
        const offsetError = wrap(
          course - heading
        );

        if (Math.abs(offsetError) < 45) {
          mem._v8HeadingOffset = clamp(
            0.98 * mem._v8HeadingOffset +
              0.02 * offsetError,
            -35,
            35
          );
        }
      }
    }

    mem._v8SampleX = x;
    mem._v8SampleY = y;
    mem._v8SampleT = now;
  }

  const oldHasTarget =
    finite(mem._v8LastTargetX) &&
    finite(mem._v8LastTargetY);

  const targetChanged =
    targetIndex !== mem._v8TargetIndex ||
    hasTarget !== oldHasTarget ||
    (
      hasTarget &&
      oldHasTarget &&
      Math.hypot(
        targetX - mem._v8LastTargetX,
        targetY - mem._v8LastTargetY
      ) > 0.80
    );

  const targetDistance = hasTarget
    ? Math.hypot(
        targetX - x,
        targetY - y
      )
    : 1e9;

  if (targetChanged) {
    mem._v8TargetIndex = targetIndex;
    mem._v8LastTargetX = hasTarget ? targetX : NaN;
    mem._v8LastTargetY = hasTarget ? targetY : NaN;

    mem._v8Mode = 0;
    mem._v8Stall = 0;
    mem._v8Steer = 0;

    mem._v8AvoidStart = now;
    mem._v8HitDist = targetDistance;
    mem._v8BestDist = targetDistance;
    mem._v8LastProgress = now;
    mem._v8ClearSince = 0;
    mem._v8LeaveUntil = 0;
    mem._v8LastSwitch = now;
    mem._v8RecoverCount = 0;
    mem._v8SideBias =
      targetIndex % 2 === 0 ? 1 : -1;
  }

  mem._v8PrevX = x;
  mem._v8PrevY = y;
  mem._v8LastHeading = heading;
  mem._v8LastT = now;

  const raw = new Array(5);

  for (let i = 0; i < 5; i++) {
    let q =
      obs.rays &&
      finite(obs.rays[i])
        ? obs.rays[i]
        : 10;

    raw[i] = clamp(q, 0, 10);
  }

  if (finite(obs.distanceAhead)) {
    raw[2] = Math.min(
      raw[2],
      clamp(obs.distanceAhead, 0, 10)
    );
  }

  if (
    !Array.isArray(mem._v8RayFilter) ||
    mem._v8RayFilter.length !== 5
  ) {
    mem._v8RayFilter = raw.slice();
  } else {
    for (let i = 0; i < 5; i++) {
      if (!finite(mem._v8RayFilter[i])) {
        mem._v8RayFilter[i] = raw[i];
      }

      const alpha =
        raw[i] < mem._v8RayFilter[i]
          ? 0.76
          : 0.30;

      mem._v8RayFilter[i] +=
        alpha * (
          raw[i] - mem._v8RayFilter[i]
        );
    }
  }

  const risk = new Array(5);
  const geom = new Array(5);

  for (let i = 0; i < 5; i++) {
    risk[i] = Math.min(
      raw[i],
      mem._v8RayFilter[i]
    );

    geom[i] =
      raw[i] < mem._v8RayFilter[i]
        ? raw[i]
        : 0.72 * raw[i] +
          0.28 * mem._v8RayFilter[i];
  }

  const navHeading = wrap(
    heading + mem._v8HeadingOffset
  );

  const predictedHeading = wrap(
    navHeading +
      clamp(
        mem._v8HeadingRate * 0.15,
        -22,
        22
      )
  );

  const globalTargetBearing = hasTarget
    ? Math.atan2(
        targetY - y,
        targetX - x
      ) / DEG
    : 0;

  const targetBearing = wrap(
    globalTargetBearing - predictedHeading
  );

  const targetAngle = Math.abs(
    targetBearing
  );

  const rightRiskNear = Math.min(
    risk[0],
    risk[1]
  );

  const leftRiskNear = Math.min(
    risk[3],
    risk[4]
  );

  const rightNear = Math.min(
    geom[0],
    geom[1]
  );

  const leftNear = Math.min(
    geom[3],
    geom[4]
  );

  const centerRange = risk[2];

  const corridorLike =
    geom[2] > 1.70 &&
    rightNear < 2.10 &&
    leftNear < 2.10 &&
    Math.abs(rightNear - leftNear) < 0.90;

  const narrowCorridor =
    corridorLike &&
    Math.min(rightNear, leftNear) < 1.02;

  const corridorSafe =
    corridorLike &&
    centerRange > 1.85 &&
    geom[1] > 0.65 &&
    geom[3] > 0.65;

  const frontLimit =
    1.78 +
    Math.min(
      0.65,
      speed * 0.42
    );

  const frontRisk = Math.min(
    risk[2],
    risk[1] + 0.42,
    risk[3] + 0.42,
    risk[0] + 0.75,
    risk[4] + 0.75
  );

  const forwardClear =
    corridorSafe
      ? centerRange
      : Math.min(
          centerRange,
          risk[1] + 0.66,
          risk[3] + 0.66
        );

  let frontBlocked =
    centerRange < frontLimit;

  if (
    corridorSafe &&
    centerRange >
      2.05 + speed * 0.12
  ) {
    frontBlocked = false;
  }

  if (
    !corridorLike &&
    frontRisk <
      1.45 +
      Math.min(0.38, speed * 0.25)
  ) {
    frontBlocked = true;
  }

  if (
    corridorLike &&
    !corridorSafe &&
    (
      (
        risk[1] < 0.48 &&
        centerRange < 2.0
      ) ||
      (
        risk[3] < 0.48 &&
        centerRange < 2.0
      )
    )
  ) {
    frontBlocked = true;
  }

  const hardFront =
    centerRange < 0.66 ||
    (
      !corridorLike &&
      frontRisk < 0.58
    ) ||
    (
      !corridorLike &&
      (
        (
          risk[1] < 0.43 &&
          centerRange < 1.90
        ) ||
        (
          risk[3] < 0.43 &&
          centerRange < 1.90
        )
      )
    ) ||
    (
      corridorLike &&
      !corridorSafe &&
      Math.min(risk[1], risk[3]) < 0.38 &&
      centerRange < 1.80
    );

  const rightAsym =
    rightRiskNear + 0.22 < leftRiskNear &&
    rightRiskNear < 2.35;

  const leftAsym =
    leftRiskNear + 0.22 < rightRiskNear &&
    leftRiskNear < 2.35;

  const sideClose =
    Math.min(rightRiskNear, leftRiskNear) <
    0.78 + Math.min(0.12, speed * 0.05);

  const hardSide =
    Math.min(rightRiskNear, leftRiskNear) < 0.46;

  const sideCaution =
    !corridorLike &&
    (
      (
        rightAsym &&
        rightRiskNear < 2.35
      ) ||
      (
        leftAsym &&
        leftRiskNear < 2.35
      )
    );

  const sideThreat =
    (
      !corridorLike &&
      (
        (
          rightAsym &&
          (
            rightRiskNear < 1.92 ||
            (
              speed > 0.72 &&
              rightRiskNear < 2.18
            )
          )
        ) ||
        (
          leftAsym &&
          (
            leftRiskNear < 1.92 ||
            (
              speed > 0.72 &&
              leftRiskNear < 2.18
            )
          )
        )
      )
    ) ||
    (
      corridorLike &&
      Math.abs(rightRiskNear - leftRiskNear) > 0.65 &&
      Math.min(rightRiskNear, leftRiskNear) < 0.90 &&
      centerRange < 3.50
    );

  const edge = 1.60;
  const edgeSpan = 1.20;

  let pushX = 0;
  let pushY = 0;

  if (x < edge) {
    pushX += clamp(
      (edge - x) / edgeSpan,
      0,
      1.6
    );
  }

  if (x > 40 - edge) {
    pushX -= clamp(
      (x - (40 - edge)) / edgeSpan,
      0,
      1.6
    );
  }

  if (y < edge) {
    pushY += clamp(
      (edge - y) / edgeSpan,
      0,
      1.6
    );
  }

  if (y > 40 - edge) {
    pushY -= clamp(
      (y - (40 - edge)) / edgeSpan,
      0,
      1.6
    );
  }

  const pushMagnitude = Math.hypot(
    pushX,
    pushY
  );

  let boundaryRel = 0;
  let inwardDot = 1;
  let boundarySteer = 0;

  if (pushMagnitude > 0.001) {
    const inwardBearing =
      Math.atan2(pushY, pushX) / DEG;

    boundaryRel = wrap(
      inwardBearing - predictedHeading
    );

    inwardDot = Math.cos(
      boundaryRel * DEG
    );

    boundarySteer =
      0.50 *
      clamp(boundaryRel / 90, -1, 1) *
      clamp(
        0.38 + pushMagnitude,
        0.38,
        1.25
      );
  }

  let boundaryCap = 1;

  if (
    pushMagnitude > 0.35 &&
    inwardDot < 0.62
  ) {
    boundaryCap = 0.68;
  }

  if (
    pushMagnitude > 0.75 &&
    inwardDot < 0.36
  ) {
    boundaryCap = 0.34;
  }

  if (
    pushMagnitude > 1.05 &&
    inwardDot < 0.10
  ) {
    boundaryCap = 0.10;
  }

  const boundaryThreat =
    (
      pushMagnitude > 0.25 &&
      inwardDot < 0.46
    ) ||
    x < 1.00 ||
    x > 39.00 ||
    y < 1.00 ||
    y > 39.00;

  const hardBoundary =
    x < 0.55 ||
    x > 39.45 ||
    y < 0.55 ||
    y > 39.45;

  function danger(q, limit) {
    if (q >= limit) return 0;

    return clamp(
      (limit - q) /
        Math.max(0.22, limit - 0.40),
      0,
      1
    );
  }

  const rightDanger = danger(
    rightRiskNear,
    1.65
  );

  const leftDanger = danger(
    leftRiskNear,
    1.65
  );

  function clearanceAt(angle) {
    angle = clamp(angle, -60, 60);

    if (angle <= -30) {
      const u = (angle + 60) / 30;
      return risk[0] * (1 - u) +
        risk[1] * u;
    }

    if (angle <= 0) {
      const u = (angle + 30) / 30;
      return risk[1] * (1 - u) +
        risk[2] * u;
    }

    if (angle <= 30) {
      const u = angle / 30;
      return risk[2] * (1 - u) +
        risk[3] * u;
    }

    const u = (angle - 30) / 30;
    return risk[3] * (1 - u) +
      risk[4] * u;
  }

  function sideOpening(side) {
    let a;
    let b;

    if (side > 0) {
      a = 3;
      b = 4;
    } else {
      a = 1;
      b = 0;
    }

    const va =
      0.68 * geom[a] +
      0.32 * risk[a];

    const vb =
      0.68 * geom[b] +
      0.32 * risk[b];

    return Math.min(va, vb);
  }

  function chooseTurnSide() {
    if (
      boundaryThreat &&
      Math.abs(boundaryRel) > 16
    ) {
      return boundaryRel >= 0 ? 1 : -1;
    }

    if (
      rightAsym &&
      !leftAsym
    ) {
      return 1;
    }

    if (
      leftAsym &&
      !rightAsym
    ) {
      return -1;
    }

    const leftOpen = sideOpening(1);
    const rightOpen = sideOpening(-1);

    if (
      targetBearing > 24 &&
      leftOpen > 0.82 &&
      leftOpen >= rightOpen * 0.72
    ) {
      return 1;
    }

    if (
      targetBearing < -24 &&
      rightOpen > 0.82 &&
      rightOpen >= leftOpen * 0.72
    ) {
      return -1;
    }

    if (leftOpen > rightOpen + 0.26) {
      return 1;
    }

    if (rightOpen > leftOpen + 0.26) {
      return -1;
    }

    return mem._v8SideBias >= 0 ? 1 : -1;
  }

  function targetPathClear() {
    if (targetAngle > 82) {
      return false;
    }

    const a = clamp(
      targetBearing,
      -60,
      60
    );

    const c0 = clearanceAt(a);
    const c1 = clearanceAt(
      clamp(a - 12, -60, 60)
    );
    const c2 = clearanceAt(
      clamp(a + 12, -60, 60)
    );

    const pathLimit =
      corridorLike ? 0.68 : 1.05;

    if (
      targetAngle < 38 &&
      frontBlocked
    ) {
      return false;
    }

    return (
      Math.min(c0, c1, c2) > pathLimit &&
      !hardFront &&
      !hardSide &&
      !boundaryThreat &&
      !hardBoundary
    );
  }

  function drive(base, turn, urgent, hard) {
    if (!finite(base)) base = 0;
    if (!finite(turn)) turn = 0;

    base = clamp(base, -1, 1);
    turn = clamp(turn, -0.90, 0.90);

    let actualTurn;

    if (hard) {
      actualTurn = turn;
      mem._v8Steer = turn;
    } else {
      const oldTurn = finite(mem._v8Steer)
        ? mem._v8Steer
        : 0;

      let alpha = urgent ? 0.48 : 0.22;

      if (oldTurn * turn < 0) {
        alpha = urgent ? 0.68 : 0.52;
      } else if (
        Math.abs(turn - oldTurn) > 0.25
      ) {
        alpha = Math.max(
          alpha,
          urgent ? 0.54 : 0.34
        );
      }

      mem._v8Steer =
        oldTurn +
        alpha * (turn - oldTurn);

      actualTurn = mem._v8Steer;
    }

    const desiredL = clamp(
      base - actualTurn,
      -1,
      1
    );

    const desiredR = clamp(
      base + actualTurn,
      -1,
      1
    );

    const oldL = finite(mem._v8CmdL)
      ? mem._v8CmdL
      : 0;

    const oldR = finite(mem._v8CmdR)
      ? mem._v8CmdR
      : 0;

    const timeScale = clamp(
      dt / 0.05,
      0.70,
      1.60
    );

    let step =
      hard
        ? 0.36
        : (urgent ? 0.12 : 0.065);

    step *= timeScale;

    function slew(oldValue, newValue) {
      let localStep = step;

      if (newValue < oldValue) {
        localStep = Math.max(
          localStep,
          urgent ? 0.17 : 0.09
        );
      }

      if (newValue * oldValue < 0) {
        localStep = Math.max(
          localStep,
          hard ? 0.32 : (urgent ? 0.21 : 0.13)
        );
      }

      return oldValue + clamp(
        newValue - oldValue,
        -localStep,
        localStep
      );
    }

    mem._v8CmdL = clamp(
      slew(oldL, desiredL),
      -1,
      1
    );

    mem._v8CmdR = clamp(
      slew(oldR, desiredR),
      -1,
      1
    );

    return {
      left: mem._v8CmdL,
      right: mem._v8CmdR
    };
  }

  function beginAvoid(side) {
    side = side >= 0 ? 1 : -1;

    mem._v8Mode = 1;
    mem._v8TurnSide = side;
    mem._v8WallSide = -side;
    mem._v8Steer = 0;

    mem._v8AvoidStart = now;
    mem._v8HitDist = Math.max(
      targetDistance,
      0.85
    );
    mem._v8BestDist = targetDistance;
    mem._v8LastProgress = now;
    mem._v8ClearSince = 0;
    mem._v8LastSwitch = now;
    mem._v8LeaveUntil = now + 0.75;
    mem._v8SideBias = -side;
  }

  function beginRecovery(side) {
    if (side !== 1 && side !== -1) {
      side = chooseTurnSide();
    }

    if (
      mem._v8RecoverCount % 2 === 1 &&
      side === mem._v8TurnSide
    ) {
      side = -side;
    }

    mem._v8Mode = 2;
    mem._v8RecoverStart = now;
    mem._v8RecoverTurn = side;
    mem._v8RecoverCount += 1;
    mem._v8Stall = 0;
    mem._v8Steer = 0;
  }

  function emergencyDrive(preferred) {
    let side =
      preferred >= 0 ? 1 : -1;

    if (hardBoundary) {
      if (Math.abs(boundaryRel) > 12) {
        side = boundaryRel >= 0 ? 1 : -1;
      }
    } else if (
      hardSide &&
      !hardFront
    ) {
      if (rightRiskNear < leftRiskNear) {
        side = 1;
      } else if (leftRiskNear < rightRiskNear) {
        side = -1;
      }
    } else if (hardFront) {
      const selected = sideOpening(side);
      const alternate = sideOpening(-side);

      if (
        alternate > selected + 0.22
      ) {
        side = -side;
      }
    }

    let base =
      speed > 0.22 ? -0.10 : 0;

    if (
      hardBoundary &&
      inwardDot > 0.35
    ) {
      base = 0;
    }

    const turn =
      side * 0.52 -
      clamp(
        mem._v8HeadingRate * 0.00045,
        -0.08,
        0.08
      );

    return drive(
      base,
      turn,
      true,
      true
    );
  }

  if (!hasTarget) {
    return drive(
      0,
      0,
      true,
      true
    );
  }

  if (targetDistance < 0.70) {
    return drive(
      0,
      0,
      true,
      true
    );
  }

  if (mem._v8Mode === 2) {
    const phase =
      now - mem._v8RecoverStart;

    const side =
      mem._v8RecoverTurn >= 0 ? 1 : -1;

    if (phase < 0.12) {
      return drive(
        0,
        0,
        true,
        true
      );
    }

    if (phase < 0.40) {
      return drive(
        -0.20,
        0,
        true,
        false
      );
    }

    if (phase < 1.28) {
      return drive(
        0,
        side * 0.43,
        true,
        true
      );
    }

    mem._v8Mode = 1;
    mem._v8TurnSide = side;
    mem._v8WallSide = -side;
    mem._v8AvoidStart = now;
    mem._v8HitDist = Math.max(
      targetDistance,
      0.85
    );
    mem._v8BestDist = targetDistance;
    mem._v8LastProgress = now;
    mem._v8ClearSince = 0;
    mem._v8LastSwitch = now;
    mem._v8LeaveUntil = now + 0.85;
    mem._v8SideBias = -side;
  }

  const modeHazard =
    frontBlocked ||
    sideThreat ||
    hardSide ||
    boundaryThreat ||
    hardBoundary;

  const severeHazard =
    hardFront ||
    hardSide ||
    hardBoundary;

  if (
    mem._v8Mode === 0 &&
    targetDistance > 0.82 &&
    modeHazard &&
    (
      now >= mem._v8LeaveUntil ||
      severeHazard
    )
  ) {
    beginAvoid(
      chooseTurnSide()
    );
  }

  if (
    mem._v8Mode === 0 &&
    mem._v8Stall > 1.25 &&
    targetDistance > 1.0
  ) {
    beginRecovery(
      chooseTurnSide()
    );

    return drive(
      0,
      0,
      true,
      true
    );
  }

  if (mem._v8Mode === 1) {
    if (
      targetDistance <
      mem._v8BestDist - 0.04
    ) {
      mem._v8BestDist = targetDistance;
      mem._v8LastProgress = now;
    }

    const elapsed =
      now - mem._v8AvoidStart;

    const needed = clamp(
      0.25 +
        0.018 *
        Math.min(mem._v8HitDist, 20),
      0.28,
      0.58
    );

    const madeProgress =
      targetDistance <
      mem._v8HitDist - needed;

    const relaxed =
      elapsed > 2.50 &&
      targetDistance <
        mem._v8HitDist + 0.12 &&
      targetPathClear();

    if (
      elapsed > 0.90 &&
      (
        madeProgress ||
        relaxed
      ) &&
      targetPathClear()
    ) {
      if (mem._v8ClearSince <= 0) {
        mem._v8ClearSince = now;
      }
    } else {
      mem._v8ClearSince = 0;
    }

    if (
      mem._v8ClearSince > 0 &&
      now - mem._v8ClearSince > 0.34
    ) {
      mem._v8Mode = 0;
      mem._v8Steer = 0;
      mem._v8ClearSince = 0;
      mem._v8LeaveUntil = now + 0.95;
    }

    if (mem._v8Mode === 1) {
      const noProgress =
        elapsed > 5.5 &&
        now - mem._v8LastProgress > 4.2;

      if (
        noProgress ||
        elapsed > 19.0
      ) {
        let recoverySide =
          chooseTurnSide();

        if (
          recoverySide ===
          mem._v8TurnSide
        ) {
          recoverySide = -recoverySide;
        }

        beginRecovery(
          recoverySide
        );

        return drive(
          0,
          0,
          true,
          true
        );
      }
    }
  }

  if (mem._v8Mode === 1) {
    let turnSide =
      mem._v8TurnSide >= 0 ? 1 : -1;

    const elapsed =
      now - mem._v8AvoidStart;

    if (
      elapsed > 1.05 &&
      now - mem._v8LastSwitch > 0.75
    ) {
      const selected =
        sideOpening(turnSide);

      const alternate =
        sideOpening(-turnSide);

      if (
        selected < 1.05 &&
        alternate > selected + 0.28 &&
        alternate > 1.00
      ) {
        turnSide = -turnSide;
        mem._v8TurnSide = turnSide;
        mem._v8WallSide = -turnSide;
        mem._v8LastSwitch = now;
        mem._v8SideBias = -turnSide;
      }
    }

    const wallSide =
      mem._v8WallSide < 0 ? -1 : 1;

    const wallDistance =
      wallSide < 0
        ? Math.min(geom[0], geom[1])
        : Math.min(geom[3], geom[4]);

    let steer = 0;

    if (elapsed < 1.25) {
      steer +=
        turnSide *
        (
          0.24 *
          (1 - elapsed / 1.25) +
          0.035
        );
    }

    if (frontBlocked) {
      steer +=
        turnSide *
        (
          0.18 +
          0.30 *
          danger(
            centerRange,
            frontLimit
          )
        );
    } else if (forwardClear < 2.75) {
      steer +=
        turnSide *
        0.07 *
        danger(
          forwardClear,
          2.75
