        ? (finite(mem._stuckTime) ? mem._stuckTime : 0) + elapsed
        : Math.max(0, (finite(mem._stuckTime) ? mem._stuckTime : 0) -
                      1.1 * elapsed);

      mem._progT = now;
      mem._progX = x;
      mem._progY = y;
      mem._progD = goalDist;

      const cooldownReady = !finite(mem._recCooldown) ||
        now >= mem._recCooldown;
      if (mem._stuckTime > 2.0 && cooldownReady && goalDist > 2.0) {
        if (leftClear > rightClear + 0.2) mem._recDir = 1;
        else if (rightClear > leftClear + 0.2) mem._recDir = -1;
        else mem._recDir = goalRel >= 0 ? 1 : -1;

        if (edgeCurrent < 1.0) {
          const centerBearing = Math.atan2(20 - y, 20 - x) / rad;
          if (Math.abs(wrap(centerBearing - heading)) > 8) {
            mem._recDir = wrap(centerBearing - heading) > 0 ? 1 : -1;
          }
        }

        mem._recStart = now;
        mem._recUntil = now + 0.90;
        mem._recCooldown = now + 4.0;
        mem._stuckTime = 0;
        recovering = true;
      }
    }
  }

  if (recovering) {
    const dir = finite(mem._recDir) ? mem._recDir : 1;
    const phase = now - mem._recStart;
    if (phase < 0.38 && edgeCurrent > 1.15) {
      const back = -0.27;
      const pivot = 0.08 * dir;
      return {
        left: clamp(back - pivot, -1, 1),
        right: clamp(back + pivot, -1, 1)
      };
    }
    const pivot = 0.19 * dir;
    return { left: -pivot, right: pivot };
  }

  const look = Math.min(
    4.5,
    3.15 + 0.65 * speed,
    Math.max(1.5, goalDist + 0.4)
  );
  const obstacles = [];
  for (const p of map) {
    const dx = p.x - x;
    const dy = p.y - y;
    const d = Math.hypot(dx, dy);
    const age = Math.max(0, now - p.t);
    if (d > look + 1.6 || age > 1.45) continue;
    obstacles.push({
      dx,
      dy,
      d,
      weight: 0.25 + 0.75 * Math.exp(-age / 0.8)
    });
  }

  let urgent = frontDanger < 2.0 ||
    edgeCurrent < 1.1 || edgeForward < 1.4;
  let emergency = frontDanger < 0.78 || ranges[2] < 0.62 ||
    edgeCurrent < 0.32 || edgeForward < 0.48;

  const previousAim = finite(mem._aimWorld) ? mem._aimWorld : undefined;
  const candidates = [];
  for (let a = -180; a <= 180; a += 5) candidates.push(a);
  candidates.push(goalRel);
  if (previousAim !== undefined) {
    candidates.push(wrap(previousAim - heading));
  }

  let bestWorld = goalBearing;
  let bestCost = Infinity;
  const softR = 1.28;
  const hardR = 0.78;

  for (const rel0 of candidates) {
    const rel = wrap(rel0);
    const world = wrap(heading + rel);
    const goalError = Math.abs(wrap(world - goalBearing));
    const goalRad = goalError * rad;
    const relRad = rel * rad;
    const ux = Math.cos(world * rad);
    const uy = Math.sin(world * rad);
    const absRel = Math.abs(rel);

    let cost = 3.1 * (1 - Math.cos(goalRad)) + 0.0085 * goalError;
    cost += 0.46 * (1 - Math.cos(relRad)) + 0.003 * absRel;

    if (absRel > 110) cost += 0.022 * (absRel - 110);
    if (absRel > 150 && Math.abs(goalRel) < 120) cost += 1.1;

    cost -= 0.12 * sideBias * Math.sign(rel) *
      clamp(absRel / 50, 0, 1);

    if (avoidActive && finite(mem._avoidSign)) {
      const favored = rel * mem._avoidSign;
      if (favored < -8) {
        cost += 1.2 + 0.004 * Math.min(120, -favored);
      } else if (favored > 8) {
        cost -= 0.14 * clamp(favored / 60, 0, 1);
      }
    }

    let obstacleCost = 0;
    for (const p of obstacles) {
      if (p.d > look + 1.0) continue;
      const projection = p.dx * ux + p.dy * uy;
      if (projection < -0.35 || projection > look + 1.0) continue;

      const along = clamp(projection, 0, look);
      const sep = Math.hypot(
        p.dx - along * ux,
        p.dy - along * uy
      );

      if (sep < softR) {
        const q = (softR - sep) / softR;
        obstacleCost += 9.0 * q * q * p.weight;
      }
      if (sep < hardR) {
        const q = (hardR - sep) / hardR;
        obstacleCost += 14.0 * q * q * p.weight;
      }
      if (projection < 1.15 && sep < 1.45) {
        const q = (1.15 - Math.max(0, projection)) / 1.15;
        obstacleCost += 4.0 * q * q * p.weight;
      }
    }
    cost += Math.min(40, obstacleCost);

    const edgeD = edgeRayDistance(world);
    if (edgeD < look) {
      cost += 11 + 6 * (look - edgeD);
    } else if (edgeD < look + 0.6) {
      const q = look + 0.6 - edgeD;
      cost += 2.2 * q * q;
    }
    if (edgeD < 0.55) cost += 28;

    if (previousAim !== undefined) {
      cost += 0.004 * Math.abs(wrap(world - previousAim));
    }

    if (cost < bestCost) {
      bestCost = cost;
      bestWorld = world;
    }
  }

  let aimWorld = bestWorld;
  if (previousAim !== undefined) {
    const delta = wrap(aimWorld - previousAim);
    const maxStep = emergency ? 14 : (urgent ? 9 : 5);
    aimWorld = wrap(previousAim + clamp(delta, -maxStep, maxStep));
  }
  mem._aimWorld = aimWorld;

  const error = wrap(aimWorld - heading);
  const errorRad = error * rad;
  const aimUx = Math.cos(aimWorld * rad);
  const aimUy = Math.sin(aimWorld * rad);

  let nearestBlock = look + 0.9;
  for (const p of obstacles) {
    const projection = p.dx * aimUx + p.dy * aimUy;
    if (projection < -0.1 || projection > look + 0.9) continue;

    const along = clamp(projection, 0, look);
    const sep = Math.hypot(
      p.dx - along * aimUx,
      p.dy - along * aimUy
    );
    if (sep < 0.98) {
      const intrusion = Math.sqrt(Math.max(0, 0.98 * 0.98 - sep * sep));
      nearestBlock = Math.min(
        nearestBlock,
        Math.max(0.05, projection - intrusion - 0.08)
      );
    }
  }

  const edgeAim = edgeRayDistance(aimWorld);
  const safeDist = Math.min(
    look + 0.9,
    nearestBlock,
    Math.max(0, edgeAim - 0.25)
  );

  if (safeDist < 1.4) urgent = true;
  if (safeDist < 0.45) emergency = true;

  let desiredSpeed = 1.02;
  if (safeDist < 2.6) {
    desiredSpeed = Math.min(desiredSpeed, 0.18 + 0.38 * safeDist);
  }
  if (frontDanger < 3.2) {
    desiredSpeed = Math.min(desiredSpeed, 0.20 + 0.25 * frontDanger);
  }
  if (avoidActive) desiredSpeed = Math.min(desiredSpeed, 0.78);
  if (frontDanger < 2.3 && avoidActive) {
    desiredSpeed = Math.min(desiredSpeed, 0.55);
  }
  if (frontDanger < 1.0) desiredSpeed = Math.min(desiredSpeed, 0.18);
  if (frontDanger < 0.68) desiredSpeed = Math.min(desiredSpeed, 0.10);
  if (goalDist < 3.0) {
    desiredSpeed = Math.min(desiredSpeed, 0.28 + 0.28 * goalDist);
  }

  if (Math.abs(error) > 65) desiredSpeed = Math.min(desiredSpeed, 0.72);
  if (Math.abs(error) > 100) desiredSpeed = Math.min(desiredSpeed, 0.42);
  if (Math.abs(error) > 140) desiredSpeed = Math.min(desiredSpeed, 0.20);
  if (edgeCurrent < 1.0) desiredSpeed = Math.min(desiredSpeed, 0.42);
  if (edgeCurrent < 0.45) desiredSpeed = Math.min(desiredSpeed, 0.20);
  if (edgeAim < 1.2) desiredSpeed = Math.min(desiredSpeed, 0.35);
  if (Math.abs(yawRate) > 115) desiredSpeed = Math.min(desiredSpeed, 0.52);
  if (safeDist < 0.38) desiredSpeed = Math.min(desiredSpeed, 0.12);

  let throttle =
    0.36 * (desiredSpeed / 1.05) +
    1.05 * (desiredSpeed - speedSigned);
  throttle = clamp(throttle, -0.48, 0.60);

  const alignment = 0.35 + 0.65 * Math.max(0, Math.cos(errorRad));
  let base = throttle > 0 ? throttle * alignment : throttle;
  if (Math.abs(error) > 120 && base > 0) base = Math.min(base, 0.02);

  if (frontDanger < 1.35 && speed > 0.45) {
    base = Math.min(base, -0.12);
  }
  if (frontDanger < 0.80 && speed > 0.20) {
    base = Math.min(base, -0.26);
  }
  if (ranges[2] < 0.62 && speed > 0.15) {
    base = Math.min(base, -0.28);
  }
  if (safeDist < 0.38 && speed > 0.16) {
    base = Math.min(base, -0.24);
  }
  if (edgeForward < 0.58 && speed > 0.18) {
    base = Math.min(base, -0.24);
  }

  const turnLimit = emergency ? 0.25 : (urgent ? 0.22 : 0.19);
  const desiredTurn = clamp(
    0.0028 * error - 0.00125 * yawRate,
    -turnLimit,
    turnLimit
  );
  const oldTurn = finite(mem._turn) ? mem._turn : 0;
  const turnStep = emergency ? 0.055 : (urgent ? 0.040 : 0.030);
  const turn = clamp(
    oldTurn + clamp(desiredTurn - oldTurn, -turnStep, turnStep),
    -turnLimit,
    turnLimit
  );
  mem._turn = turn;

  return {
    left: clamp(base - turn, -1, 1),
    right: clamp(base + turn, -1, 1)
  };
}

function act(obs, mem) {
  const DEG = Math.PI / 180;
  const N = 160;
  const CELL = 0.25;
  const GRID = N * N;

  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
  function wrap(a) {
    while (a > Math.PI) a -= 2 * Math.PI;
    while (a < -Math.PI) a += 2 * Math.PI;
    return a;
  }

  if (!mem.init) {
    mem.init = true;
    mem.occ = new Int16Array(GRID);
    mem.g = new Float32Array(GRID);
    mem.f = new Float32Array(GRID);
    mem.came = new Int32Array(GRID);
    mem.visited = new Uint8Array(GRID);
    mem.bias = 0;
    mem.calibrated = false;
    mem.biasUpdates = 0;
    mem.lastX = obs.x;
    mem.lastY = obs.y;
    mem.lastT = obs.t;
    mem.lastPlan = -10;
    mem.lastTargetIndex = -1;
    mem.path = [];
    mem.mode = null;
    mem.stuckTime = 0;
    mem.modeUntil = 0;
    mem.recoveryDir = 1;
  }

  const t = obs.t;
  const x = obs.x;
  const y = obs.y;
  const heading = obs.heading * DEG;
  const rays = obs.rays;

  // Bias estimation from GPS movement
  const dx = x - mem.lastX;
  const dy = y - mem.lastY;
  const moved = Math.hypot(dx, dy);
  if (moved > 0.02 && obs.speed > 0.1) {
    const measured = Math.atan2(dy, dx);
    const newBias = wrap(measured - heading);
    if (!mem.calibrated) {
      mem.bias = wrap(mem.bias + 0.3 * wrap(newBias - mem.bias));
      mem.biasUpdates++;
      if (mem.biasUpdates > 5 || t > 1.5) mem.calibrated = true;
    } else {
      mem.bias = wrap(mem.bias + 0.05 * wrap(newBias - mem.bias));
    }
  }
  mem.lastX = x;
  mem.lastY = y;

  // Calibration phase: drive forward to learn heading bias
  if (!mem.calibrated) {
    let front = rays[2];
    let turn = 0;
    if (front < 1.0) {
      turn = (rays[1] < rays[3]) ? 1 : -1;
    }
    let forward = front < 0.5 ? 0 : 0.4;
    let left = forward - turn * 0.6;
    let right = forward + turn * 0.6;
    return { left: clamp(left, -1, 1), right: clamp(right, -1, 1) };
  }

  const h = wrap(heading + mem.bias);

  // Update occupancy map from rays
  for (let i = 0; i < 5; i++) {
    let r = rays[i];
    if (r < 9.5) {
      let a = h + (i - 2) * 30 * DEG;
      let cx = Math.cos(a);
      let cy = Math.sin(a);
      let maxDist = Math.max(0, r - 0.4);
      let steps = Math.floor(maxDist / CELL);
      for (let s = 1; s <= steps; s++) {
        let px = x + s * CELL * cx;
        let py = y + s * CELL * cy;
        let gx = Math.floor(px / CELL);
        let gy = Math.floor(py / CELL);
        if (gx >= 0 && gx < N && gy >= 0 && gy < N) {
          let ii = gx + gy * N;
          if (mem.occ[ii] > -5) mem.occ[ii] -= 1;
        }
      }
      let ox = x + r * cx;
      let oy = y + r * cy;
      let rad = 0.3;
      let minx = Math.floor((ox - rad) / CELL);
      let maxx = Math.floor((ox + rad) / CELL);
      let miny = Math.floor((oy - rad) / CELL);
      let maxy = Math.floor((oy + rad) / CELL);
      for (let gy = miny; gy <= maxy; gy++) {
        if (gy < 0 || gy >= N) continue;
        for (let gx = minx; gx <= maxx; gx++) {
          if (gx < 0 || gx >= N) continue;
          let ddx = (gx + 0.5) * CELL - ox;
          let ddy = (gy + 0.5) * CELL - oy;
          if (ddx * ddx + ddy * ddy <= rad * rad) {
            let ii = gx + gy * N;
            if (mem.occ[ii] < 100) mem.occ[ii] += 3;
          }
        }
      }
    }
  }

  // Plan path to current target
  const tx = obs.targetX;
  const ty = obs.targetY;
  let needPlan = (t - mem.lastPlan > 0.5) || (obs.targetIndex !== mem.lastTargetIndex) || (mem.path.length === 0);
  if (mem.mode === 'reverse') needPlan = false;

  if (needPlan) {
    mem.path = planPath(x, y, tx, ty);
    mem.lastPlan = t;
    mem.lastTargetIndex = obs.targetIndex;
  }

  // Determine desired heading
  let desired = Math.atan2(ty - y, tx - x);
  if (mem.path && mem.path.length > 0) {
    let look = getLookahead(mem.path, x, y, 1.0);
    if (look) desired = Math.atan2(look.y - y, look.x - x);
  }

  // Reactive obstacle avoidance
  let vx = Math.cos(desired);
  let vy = Math.sin(desired);
  const SAFE = 1.6;
  for (let i = 0; i < 5; i++) {
    let r = rays[i];
    if (r < SAFE) {
      let a = h + (i - 2) * 30 * DEG;
      let w = (SAFE - r) / SAFE;
      w = w * w * 1.2;
      vx -= Math.cos(a) * w;
      vy -= Math.sin(a) * w;
    }
  }
  if (vx * vx + vy * vy > 0.01) {
    desired = Math.atan2(vy, vx);
  }

  // Recovery mode
  if (mem.mode === 'reverse') {
    let dir = mem.recoveryDir;
    let left = -0.5 - dir * 0.3;
    let right = -0.5 + dir * 0.3;
    if (t > mem.modeUntil) {
      mem.mode = null;
      mem.path = [];
    }
    return { left: clamp(left, -1, 1), right: clamp(right, -1, 1) };
  }

  // Normal driving
  let front = rays[2];
  let err = wrap(desired - h);
  let turn = clamp(err * 1.8, -1, 1);
  let forward = 0.7;
  if (front > 2.0 && Math.abs(err) < 0.4) forward = 1.0;
  else if (front > 1.2) forward = 0.7;
  else if (front > 0.7) forward = 0.4;
  else forward = 0.15;
  if (Math.abs(err) > 1.0) forward *= 0.4;

  // Stuck detection and recovery trigger
  if (obs.speed < 0.05 && forward > 0.2) {
    mem.stuckTime += 0.05;
  } else {
    mem.stuckTime = 0;
  }
  if (mem.stuckTime > 1.0) {
    mem.mode = 'reverse';
    mem.modeUntil = t + 0.5;
    mem.recoveryDir = (rays[0] + rays[1] < rays[3] + rays[4]) ? -1 : 1;
    mem.path = [];
    mem.stuckTime = 0;
    let dir = mem.recoveryDir;
    let left = -0.5 - dir * 0.3;
    let right = -0.5 + dir * 0.3;
    return { left: clamp(left, -1, 1), right: clamp(right, -1, 1) };
  }

  let left = forward - turn;
  let right = forward + turn;

  if (Math.abs(left) < 0.12 && Math.abs(left) > 0) left = left > 0 ? 0.12 : -0.12;
  if (Math.abs(right) < 0.12 && Math.abs(right) > 0) right = right > 0 ? 0.12 : -0.12;

  return { left: clamp(left, -1, 1), right: clamp(right, -1, 1) };

  // --- Helper functions (hoisted) ---
  function planPath(sx, sy, tx, ty) {
    let scx = clamp(Math.floor(sx / CELL), 1, N - 2);
    let scy = clamp(Math.floor(sy / CELL), 1, N - 2);
    let tcx = clamp(Math.floor(tx / CELL), 1, N - 2);
    let tcy = clamp(Math.floor(ty / CELL), 1, N - 2);
    let targetIdx = -1;
    let maxR = 6;
    outer:
    for (let r = 0; r <= maxR; r++) {
      for (let dy = -r; dy <= r; dy++) {
        for (let dx = -r; dx <= r; dx++) {
          if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
          let nx = tcx + dx;
          let ny = tcy + dy;
          if (nx >= 1 && nx < N - 1 && ny >= 1 && ny < N - 1) {
            let ii = nx + ny * N;
            if (mem.occ[ii] < 4) {
              targetIdx = ii;
              tcx = nx;
              tcy = ny;
              break outer;
            }
          }
        }
      }
    }
    if (targetIdx === -1) targetIdx = tcx + tcy * N;

    let startIdx = scx + scy * N;
    if (mem.occ[startIdx] >= 4) {
      let found = false;
      for (let r = 1; r <= 5 && !found; r++) {
        for (let dy = -r; dy <= r && !found; dy++) {
          for (let dx = -r; dx <= r && !found; dx++) {
            if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
            let nx = scx + dx;
            let ny = scy + dy;
            if (nx >= 1 && nx < N - 1 && ny >= 1 && ny < N - 1) {
              let ii = nx + ny * N;
              if (mem.occ[ii] < 4) {
                startIdx = ii;
                scx = nx;
                scy = ny;
                found = true;
              }
            }
          }
        }
      }
    }

    mem.g.fill(Infinity);
    mem.came.fill(-1);
    mem.visited.fill(0);
    let heap = [];
    function hPush(i) {
      heap.push(i);
      let ci = heap.length - 1;
      while (ci > 0) {
        let pi = (ci - 1) >> 1;
        if (mem.f[heap[pi]] <= mem.f[heap[ci]]) break;
        let tmp = heap[pi]; heap[pi] = heap[ci]; heap[ci] = tmp;
        ci = pi;
      }
    }
    function hPop() {
      let ret = heap[0];
      let last = heap.pop();
      if (heap.length > 0) {
        heap[0] = last;
        let ci = 0;
        while (true) {
          let li = ci * 2 + 1;
          let ri = li + 1;
          let mi = ci;
          if (li < heap.length && mem.f[heap[li]] < mem.f[heap[mi]]) mi = li;
          if (ri < heap.length && mem.f[heap[ri]] < mem.f[heap[mi]]) mi = ri;
          if (mi === ci) break;
          let tmp = heap[ci]; heap[ci] = heap[mi]; heap[mi] = tmp;
          ci = mi;
        }
      }
      return ret;
    }
    function octile(ax, ay, bx, by) {
      let dx = Math.abs(ax - bx);
      let dy = Math.abs(ay - by);
      return Math.max(dx, dy) + 0.414 * Math.min(dx, dy);
    }

    mem.g[startIdx] = 0;
    mem.f[startIdx] = octile(scx, scy, tcx, tcy);
    hPush(startIdx);
    let found = false;
    while (heap.length > 0) {
      let cur = hPop();
      if (mem.visited[cur]) continue;
      mem.visited[cur] = 1;
      if (cur === targetIdx) { found = true; break; }
      let cx = cur % N;
      let cy = (cur / N) | 0;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dy === 0) continue;
          let nx = cx + dx;
          let ny = cy + dy;
          if (nx < 1 || nx >= N - 1 || ny < 1 || ny >= N - 1) continue;
          let ni = nx + ny * N;
          if (mem.occ[ni] >= 4) continue;
          if (dx !== 0 && dy !== 0) {
            if (mem.occ[(cx + dx) + cy * N] >= 4 || mem.occ[cx + (cy + dy) * N] >= 4) continue;
          }
          let step = (dx !== 0 && dy !== 0) ? 1.414 : 1.0;
          let v = mem.occ[ni];
          if (v < 0) step *= 1.0;
          else if (v === 0) step *= 1.8;
          else step *= 3.0;
          let ng = mem.g[cur] + step;
          if (ng < mem.g[ni]) {
            mem.g[ni] = ng;
            mem.came[ni] = cur;
            mem.f[ni] = ng + octile(nx, ny, tcx, tcy);
            hPush(ni);
          }
        }
      }
    }
    if (!found) return null;
    let path = [];
    let cur = targetIdx;
    while (cur !== -1 && cur !== startIdx) {
      let cx = cur % N;
      let cy = (cur / N) | 0;
      path.push({ x: (cx + 0.5) * CELL, y: (cy + 0.5) * CELL });
      cur = mem.came[cur];
    }
    path.reverse();
    return path;
  }

  function getLookahead(path, px, py, lookDist) {
    let bestIdx = 0;
    let bestD = Infinity;
    for (let i = 0; i < path.length; i++) {
      let d = (path[i].x - px) ** 2 + (path[i].y - py) ** 2;
      if (d < bestD) {
        bestD = d;
        bestIdx = i;
      }
    }
    let candidate = path[path.length - 1];
    for (let i = bestIdx; i < path.length; i++) {
      let d = Math.hypot(path[i].x - px, path[i].y - py);
      if (d > lookDist) {
        candidate = path[i];
        break;
      }
    }
    if (!lineOfSight(px, py, candidate.x, candidate.y)) {
      for (let i = bestIdx; i < path.length; i++) {
        let d = Math.hypot(path[i].x - px, path[i].y - py);
        if (d > 0.5) {
          if (lineOfSight(px, py, path[i].x, path[i].y)) return path[i];
          break;
        }
      }
    }
    return candidate;
  }

  function lineOfSight(x0, y0, x1, y1) {
    let dx = x1 - x0;
    let dy = y1 - y0;
    let dist = Math.hypot(dx, dy);
    let steps = Math.ceil(dist / CELL);
    for (let s = 1; s < steps; s++) {
      let t = s / steps;
      let px = x0 + dx * t;
      let py = y0 + dy * t;
      let gx = Math.floor(px / CELL);
      let gy = Math.floor(py / CELL);
      if (gx < 0 || gx >= N || gy < 0 || gy >= N) return false;
      if (mem.occ[gx + gy * N] >= 4) return false;
    }
