  const SD = 0.8;
  if (clearL < SD) avoid -= 0.9 * (SD - clearL);
  if (clearR < SD) avoid += 0.9 * (SD - clearR);
  err = wrap(err + avoid);

  // ---------- explore mode if stuck making no progress ----------
  if (t < mem.wanderUntil && !hardBoundary) {
    let bestScore = -1e9, bestAng = bearing;
    for (let i = 0; i < 5; i++) {
      const ang = wrap(mem.hEst + (i - 2) * 30 * DEG);
      const sc = Math.min(rays[i], 8) + 1.5 * Math.cos(wrap(ang - bearing)) - 0.5 * Math.abs(i - 2);
      if (sc > bestScore) { bestScore = sc; bestAng = ang; }
    }
    err = wrap(bestAng - mem.hEst);
  }

  // ---------- speed ----------
  const aerr = Math.abs(err);
  let sp = 0.8;
  if (aerr > 0.6) sp *= 0.75;
  if (aerr > 1.2) sp *= 0.6;
  if (front < 2.2) sp = Math.min(sp, 0.15 + 0.45 * (front / 2.2));
  if (front < 1.0) sp = Math.min(sp, 0.32);
  if (front < 0.55) sp = Math.min(sp, 0.08);
  const minSide = Math.min(clearL, clearR);
  if (minSide < 0.55) sp = Math.min(sp, 0.4);
  if (minSide < 0.35) sp = Math.min(sp, 0.25);
  if (distT < 1.8) sp = Math.min(sp, 0.15 + 0.35 * distT);
  if (aerr > 2.2 && front < 1.3) sp = 0;
  sp = clamp(sp, 0, 0.8);

  // ---------- steering (rate limited, no in-place spin while driving) ----------
  const turnT = clamp(err * 0.9, -1, 1);
  mem.turn = clamp(mem.turn + clamp(turnT - mem.turn, -0.08, 0.08), -1, 1);

  // ---------- emergency: very close obstacle ----------
  if (front < 0.5) {
    if (obs.speed > 0.45) {
      mem.recoverUntil = t + 0.12;
      mem.rl = -0.5; mem.rr = -0.5;
    } else {
      const s = clearL >= clearR ? 1 : -1;
      mem.recoverUntil = t + 0.3;
      mem.rl = -0.35 * s; mem.rr = 0.35 * s;
    }
    mem.lastLeft = mem.rl;
    mem.lastRight = mem.rr;
    return { left: mem.rl, right: mem.rr };
  }

  let left, right;
  if (sp < 0.18) {
    if (aerr > 0.35) {
      const s = err > 0 ? 1 : -1;
      left = -0.32 * s;
      right = 0.32 * s;
    } else {
      left = 0; right = 0;
    }
  } else {
    left = sp * (1 - 0.85 * mem.turn);
    right = sp * (1 + 0.85 * mem.turn);
    if (mem.turn > 0 && left < 0) left = 0;
    if (mem.turn < 0 && right < 0) right = 0;
    if (left > 0 && left < 0.16) left = 0.16;
    if (right > 0 && right < 0.16) right = 0.16;
  }
  left = clamp(left, -1, 1);
  right = clamp(right, -1, 1);
  mem.lastLeft = left;
  mem.lastRight = right;
  return { left, right };
}

function act(obs, mem) {
  const DEG = Math.PI / 180;
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const wrap = (a) => {
    a = (a + Math.PI) % (2 * Math.PI);
    if (a < 0) a += 2 * Math.PI;
    return a - Math.PI;
  };

  if (!mem.init) {
    mem.init = true;
    mem.bias = 0;
    mem.hEst = obs.heading * DEG;
    mem.calibState = 0;
    mem.calibStartT = 0;
    mem.calibStartX = 0;
    mem.calibStartY = 0;
    mem.calibSumC = 0;
    mem.calibN = 0;
    mem.recoverUntil = 0;
    mem.rl = 0;
    mem.rr = 0;
    mem.lastTarget = obs.targetIndex;
    mem.bestD = 1e9;
    mem.progressT = 0;
    mem.lastLeft = 0;
    mem.lastRight = 0;
    mem.posHist = [];
    mem.turn = 0;
    mem.escapeUntil = 0;
    mem.escapeAngle = 0;
  }

  const t = obs.t, x = obs.x, y = obs.y;
  const compass = obs.heading * DEG;
  const rays = obs.rays;
  const front = rays[2];
  const clearL = Math.min(rays[3], rays[4]);
  const clearR = Math.min(rays[0], rays[1]);

  mem.posHist.push([t, x, y, compass, mem.lastLeft, mem.lastRight]);
  while (mem.posHist.length > 0 && t - mem.posHist[0][0] > 2.0) mem.posHist.shift();

  // Initial heading calibration by driving straight when safe
  if (mem.calibState === 0) {
    if (front > 3.0 && x > 1.5 && x < 38.5 && y > 1.5 && y < 38.5 && Math.abs(obs.speed) < 0.2) {
      mem.calibState = 1;
      mem.calibStartT = t;
      mem.calibStartX = x;
      mem.calibStartY = y;
      mem.calibSumC = 0;
      mem.calibN = 0;
      mem.posHist = [];
    } else if (t > 2.0) {
      mem.calibState = 2;
      mem.bias = 0;
    }
  }

  if (mem.calibState === 1) {
    if (t - mem.calibStartT < 1.0 && front > 1.5) {
      mem.calibSumC += compass;
      mem.calibN++;
      mem.lastLeft = 0.6;
      mem.lastRight = 0.6;
      return { left: 0.6, right: 0.6 };
    } else {
      const dx = x - mem.calibStartX;
      const dy = y - mem.calibStartY;
      const dist = Math.hypot(dx, dy);
      if (dist > 0.3 && mem.calibN > 5) {
        const measured = Math.atan2(dy, dx);
        const avgC = mem.calibSumC / mem.calibN;
        mem.bias = wrap(measured - avgC);
      } else {
        mem.bias = 0;
      }
      mem.calibState = 2;
      mem.hEst = wrap(compass + mem.bias);
      mem.posHist = [];
    }
  }

  mem.hEst = wrap(compass + mem.bias);

  // Slow continuous bias update while driving nearly straight
  if (mem.calibState === 2 && obs.speed > 0.5 && Math.abs(mem.lastLeft - mem.lastRight) < 0.25) {
    let old = null;
    for (let i = mem.posHist.length - 1; i >= 0; i--) {
      if (t - mem.posHist[i][0] >= 0.5) { old = mem.posHist[i]; break; }
    }
    if (old) {
      const dx = x - old[1];
      const dy = y - old[2];
      const dist = Math.hypot(dx, dy);
      if (dist > 0.3) {
        const measured = Math.atan2(dy, dx);
        let sum = 0, n = 0;
        for (let i = 0; i < mem.posHist.length; i++) {
          if (mem.posHist[i][0] >= old[0]) {
            sum += mem.posHist[i][3];
            n++;
          }
        }
        if (n > 2) {
          const avgC = sum / n;
          const newBias = wrap(measured - avgC);
          mem.bias = wrap(mem.bias + 0.1 * wrap(newBias - mem.bias));
          mem.hEst = wrap(compass + mem.bias);
        }
      }
    }
  }

  const tx = obs.targetX, ty = obs.targetY;
  const distT = Math.hypot(tx - x, ty - y);
  let targetBearing = Math.atan2(ty - y, tx - x);

  if (obs.targetIndex !== mem.lastTarget) {
    mem.lastTarget = obs.targetIndex;
    mem.bestD = distT;
    mem.progressT = 0;
    mem.recoverUntil = 0;
    mem.escapeUntil = 0;
  }

  if (distT < mem.bestD - 0.1) {
    mem.bestD = distT;
    mem.progressT = 0;
  } else {
    mem.progressT += 0.05;
  }

  if (t < mem.recoverUntil) {
    return { left: mem.rl, right: mem.rr };
  }

  // Escape mode if stuck making no progress
  if (mem.progressT > 2.0 && t > mem.escapeUntil) {
    mem.escapeUntil = t + 1.0;
    let maxR = -1, maxI = 2;
    for (let i = 0; i < 5; i++) {
      if (rays[i] > maxR) { maxR = rays[i]; maxI = i; }
    }
    mem.escapeAngle = wrap(mem.hEst + (maxI - 2) * 30 * DEG);
    mem.progressT = 0;
    mem.bestD = distT;
  }
  if (t < mem.escapeUntil) {
    targetBearing = mem.escapeAngle;
  }

  // Emergency obstacle handling
  if (front < 0.5) {
    if (obs.speed > 0.3) {
      mem.recoverUntil = t + 0.2;
      mem.rl = -0.5; mem.rr = -0.5;
    } else {
      const side = clearL > clearR ? 1 : -1;
      mem.recoverUntil = t + 0.3;
      mem.rl = -0.4 * side; mem.rr = 0.4 * side;
    }
    mem.lastLeft = mem.rl; mem.lastRight = mem.rr;
    return { left: mem.rl, right: mem.rr };
  }

  // Potential field: target + boundary + obstacle repulsion
  let bx = 0, by = 0;
  const margin = 1.2;
  if (x < margin) bx += (margin - x) * 2.5;
  if (x > 40 - margin) bx -= (x - (40 - margin)) * 2.5;
  if (y < margin) by += (margin - y) * 2.5;
  if (y > 40 - margin) by -= (y - (40 - margin)) * 2.5;

  let ox = 0, oy = 0;
  const repDist = 2.0;
  for (let i = 0; i < 5; i++) {
    const r = rays[i];
    if (r < repDist) {
      const relAng = (i - 2) * 30 * DEG;
      const worldAng = mem.hEst + relAng;
      const weight = (repDist - r) / repDist;
      ox -= Math.cos(worldAng) * weight * 1.5;
      oy -= Math.sin(worldAng) * weight * 1.5;
    }
  }

  let txv = Math.cos(targetBearing);
  let tyv = Math.sin(targetBearing);

  let vx = txv + bx + ox;
  let vy = tyv + by + oy;
  let desired = Math.atan2(vy, vx);

  // Hard boundary override only when not very close to target
  if ((x < 0.8 || x > 39.2 || y < 0.8 || y > 39.2) && distT > 2.0) {
    desired = Math.atan2(20 - y, 20 - x);
  }

  let err = wrap(desired - mem.hEst);

  // Speed control
  let sp = 0.75;
  if (front < 2.5) sp = Math.min(sp, 0.2 + 0.5 * (front / 2.5));
  if (front < 1.0) sp = Math.min(sp, 0.25);
  if (front < 0.6) sp = Math.min(sp, 0.1);
  const minSide = Math.min(clearL, clearR);
  if (minSide < 0.8) sp = Math.min(sp, 0.3 + 0.5 * (minSide / 0.8));
  if (Math.abs(err) > 1.0) sp *= 0.6;
  if (Math.abs(err) > 2.0) sp = Math.min(sp, 0.2);
  if (distT < 2.0) sp = Math.min(sp, 0.2 + 0.3 * distT);
  sp = clamp(sp, 0, 0.75);

  // Steering with damping
  let turn = clamp(err * 1.2, -0.8, 0.8);
  mem.turn = mem.turn + clamp(turn - mem.turn, -0.15, 0.15);
  turn = mem.turn;

  let left, right;
  if (sp < 0.15 && Math.abs(turn) > 0.3) {
    left = -turn * 0.6;
    right = turn * 0.6;
    if (Math.abs(left) < 0.25) left = left >= 0 ? 0.25 : -0.25;
    if (Math.abs(right) < 0.25) right = right >= 0 ? 0.25 : -0.25;
  } else {
    left = sp - turn * 0.8;
    right = sp + turn * 0.8;
    if (sp > 0.15) {
      if (left < 0) left = 0;
      if (right < 0) right = 0;
      const minCmd = 0.15;
      if (left > 0 && left < minCmd) left = minCmd;
      if (right > 0 && right < minCmd) right = minCmd;
    }
  }

  left = clamp(left, -1, 1);
  right = clamp(right, -1, 1);
  mem.lastLeft = left;
  mem.lastRight = right;
  return { left, right };
}
